_NBA_LOCAL_MOMENTS_MAP: Dict[str, str] = {}
_NBA_PLAYER_MOMENT_CACHE: Dict[str, Image.Image] = {}

def get_nba_player_moment_photo(player_name: str, card: Optional[Dict[str, Any]] = None) -> Optional[Image.Image]:
    """Resolves and loads the authentic, player-specific Wikipedia / Wikimedia match moment action photo.
    Each player's image is tied directly to that specific player's name and card ID (1-to-1 mapping)."""
    global _NBA_PLAYER_MOMENT_CACHE, _NBA_LOCAL_MOMENTS_MAP
    if not player_name and not card:
        return None

    is_holo = bool(card.get("is_holo") or str(card.get("id", "")).startswith("holo_")) if card else False
    raw_cid = str(card.get("id", "")).lower().strip() if card else ""
    base_cid = raw_cid.replace("holo_", "").replace("holo-", "").strip()
    tier = str(card.get("tier", "gold")).lower().strip() if card else "gold"
    name_str = (card.get("name") if card else player_name) or player_name
    name_clean = name_str.replace("🌟", "").replace("(Holo Foil)", "").replace("(Holo)", "").replace("(Foil)", "").strip()
    clean_q = unicodedata.normalize('NFKD', name_clean).encode('ascii', 'ignore').decode('utf-8').lower().replace(".", "").replace("'", "").strip()
    raw_norm = name_clean.lower().strip()

    cache_key = f"holo_{base_cid}" if (is_holo and base_cid) else f"holo_{clean_q}" if is_holo else f"{base_cid}" if base_cid else f"{clean_q}_{tier}" if tier else clean_q

    # 1. Check in-memory cache
    if cache_key in _NBA_PLAYER_MOMENT_CACHE:
        return _NBA_PLAYER_MOMENT_CACHE[cache_key]

    # 2. Check disk cache in assets/player_moments/
    cache_dir = os.path.join(os.path.dirname(__file__), "assets", "player_moments")
    os.makedirs(cache_dir, exist_ok=True)
    safe_fname = re.sub(r'[^a-zA-Z0-9_-]', '_', cache_key) + ".jpg"
    local_path = os.path.join(cache_dir, safe_fname)

    if os.path.exists(local_path) and os.path.getsize(local_path) > 1000:
        try:
            img = Image.open(local_path)
            _NBA_PLAYER_MOMENT_CACHE[cache_key] = img
            return img
        except Exception:
            pass

    # 3. Retrieve URL based on Player + Card ID + Holo Status (1-to-1 exact mapping)
    action_url = None
    if is_holo:
        # Check dedicated player Holo Edition celebration photo
        action_url = (
            NBA_HOLO_EDITION_MOMENT_URLS.get(base_cid)
            or NBA_HOLO_EDITION_MOMENT_URLS.get(clean_q)
            or NBA_HOLO_EDITION_MOMENT_URLS.get(raw_norm)
        )
        if not action_url:
            # Find best version card for this player
            best_card = None
            for c in NBA_2K_MOBILE_CARDS:
                c_clean = unicodedata.normalize('NFKD', c["name"]).encode('ascii', 'ignore').decode('utf-8').lower().replace(".", "").replace("'", "").strip()
                if c_clean == clean_q or c["name"].lower().strip() == raw_norm:
                    if best_card is None or c.get("ovr", 0) > best_card.get("ovr", 0):
                        best_card = c
            if best_card:
                best_id = best_card["id"].lower()
                action_url = NBA_CARD_SPECIFIC_MOMENT_URLS.get(best_id)
        if not action_url:
            action_url = NBA_CARD_SPECIFIC_MOMENT_URLS.get(base_cid) or NBA_PLAYER_MOMENT_ACTION_URLS.get(raw_norm) or NBA_PLAYER_MOMENT_ACTION_URLS.get(clean_q)
    else:
        # Check player's card-specific tier moment
        action_url = NBA_CARD_SPECIFIC_MOMENT_URLS.get(base_cid)
        if not action_url:
            combo_key = f"{clean_q}_{tier}"
            action_url = NBA_CARD_SPECIFIC_MOMENT_URLS.get(combo_key)
        if not action_url:
            action_url = NBA_PLAYER_MOMENT_ACTION_URLS.get(raw_norm) or NBA_PLAYER_MOMENT_ACTION_URLS.get(clean_q)
        if not action_url:
            for k, u in NBA_PLAYER_MOMENT_ACTION_URLS.items():
                if k == clean_q or k == raw_norm or k in clean_q or clean_q in k:
                    action_url = u
                    break
        if not action_url:
            for c in NBA_2K_MOBILE_CARDS:
                c_clean = unicodedata.normalize('NFKD', c["name"]).encode('ascii', 'ignore').decode('utf-8').lower().replace(".", "").replace("'", "").strip()
                if c_clean == clean_q or c["name"].lower().strip() == raw_norm:
                    action_url = NBA_CARD_SPECIFIC_MOMENT_URLS.get(c["id"].lower())
                    if action_url:
                        break

    if action_url:
        clean_url = action_url.split("?")[0]
        try:
            req = urllib.request.Request(
                clean_url,
                headers={
                    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
                    "Accept": "image/jpeg,image/png,image/*,*/*"
                }
            )
            ctx = ssl.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            with urllib.request.urlopen(req, context=ctx, timeout=8) as resp:
                data = resp.read()
                with open(local_path, "wb") as f:
                    f.write(data)
                img = Image.open(io.BytesIO(data))
                _NBA_PLAYER_MOMENT_CACHE[cache_key] = img
                return img
        except Exception as dl_err:
            logger.debug(f"Could not fetch moment photo for {name_str} ({tier}) from {clean_url}: {dl_err}")

    # 4. Fallback to assets/moments/ directory if present
    moments_dir = os.path.join(os.path.dirname(__file__), "assets", "moments")
    if os.path.exists(moments_dir):
        if not _NBA_LOCAL_MOMENTS_MAP:
            try:
                for d in os.listdir(moments_dir):
                    full_d = os.path.join(moments_dir, d)
                    if os.path.isdir(full_d):
                        for fname in ["1.jpg", "1.png", "2.jpg", "photo.jpg"]:
                            fpath = os.path.join(full_d, fname)
                            if os.path.exists(fpath) and os.path.getsize(fpath) > 3000:
                                norm_d = unicodedata.normalize('NFKD', d).encode('ascii', 'ignore').decode('utf-8').lower().replace(".", "").replace("'", "").strip()
                                _NBA_LOCAL_MOMENTS_MAP[norm_d] = fpath
                                _NBA_LOCAL_MOMENTS_MAP[d.lower().strip()] = fpath
                                break
            except Exception:
                pass

        fpath = _NBA_LOCAL_MOMENTS_MAP.get(clean_q) or _NBA_LOCAL_MOMENTS_MAP.get(raw_norm)
        if not fpath:
            for k, p in _NBA_LOCAL_MOMENTS_MAP.items():
                if k in clean_q or clean_q in k:
                    fpath = p
                    break
                    
        if fpath and os.path.exists(fpath):
            try:
                img = Image.open(fpath)
                _NBA_PLAYER_MOMENT_CACHE[cache_key] = img
                return img
            except Exception:
                pass

    return None


TIER_DEFAULT_ACTION_URLS: Dict[str, str] = {
    "gold": "https://upload.wikimedia.org/wikipedia/commons/3/33/Alex_Caruso_%2852480104636%29_%28cropped%29.jpg",
    "ruby": "https://upload.wikimedia.org/wikipedia/commons/b/b1/1_tyrese_maxey_2026.jpg",
    "amethyst": "https://upload.wikimedia.org/wikipedia/commons/f/f2/Jalen_Brunson_2023_%28cropped%29.jpg",
    "diamond": "https://upload.wikimedia.org/wikipedia/commons/8/84/Booker_and_Curry%2C_Paris_2024_Olympic_Games.jpg",
    "galaxy_opal": "https://upload.wikimedia.org/wikipedia/commons/c/c8/Jayson_Tatum_Parade_2024.jpg",
    "dark_matter": "https://upload.wikimedia.org/wikipedia/commons/4/43/Steve_Lipfosky_--_Michael_Jordan_%281997%29.jpg",
}

_TIER_MOMENT_CACHE: Dict[str, Image.Image] = {}

def get_tier_default_moment_image(tier_key: str) -> Optional[Image.Image]:
    """Fetches, caches and returns the tier-specific iconic Wikipedia match moment image."""
    tier = tier_key.lower().strip()
    if tier in _TIER_MOMENT_CACHE:
        return _TIER_MOMENT_CACHE[tier]
    
    url = TIER_DEFAULT_ACTION_URLS.get(tier, TIER_DEFAULT_ACTION_URLS.get("gold"))
    if not url:
        return None
        
    cache_dir = os.path.join(os.path.dirname(__file__), "assets", "tier_moments")
    os.makedirs(cache_dir, exist_ok=True)
    local_path = os.path.join(cache_dir, f"{tier}.jpg")
    
    if os.path.exists(local_path) and os.path.getsize(local_path) > 1000:
        try:
            img = Image.open(local_path)
            _TIER_MOMENT_CACHE[tier] = img
            return img
        except Exception:
            pass
            
    try:
        clean_url = url.split("?")[0]
        req = urllib.request.Request(
            clean_url,
            headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
                "Accept": "image/jpeg,image/png,image/*,*/*"
            }
        )
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
        with urllib.request.urlopen(req, context=ctx, timeout=8) as resp:
            data = resp.read()
            with open(local_path, "wb") as f:
                f.write(data)
            img = Image.open(io.BytesIO(data))
            _TIER_MOMENT_CACHE[tier] = img
            return img
    except Exception as e:
        logger.debug(f"Could not load tier moment image for {tier}: {e}")
        return None


def generate_nba_card_graphic(
    card: Dict[str, Any],
    is_mystery: bool = False,
    headshot_img: Optional[Image.Image] = None
) -> io.BytesIO:
    """Generates an authentic 520x760 NBA 2K Mobile-style card graphic with real-life NBA match moments,
    dynamic player aura lighting, feathered gradient composite, holographic foil lines, OVR shield, and HUD."""
    W, H = 520, 760
    tier_key = card.get("tier", "gold").lower()
    theme = NBA_2K_CARD_THEMES.get(tier_key, NBA_2K_CARD_THEMES["gold"])
    is_holo = bool(card.get("is_holo") or str(card.get("id", "")).startswith("holo_"))

    card_img = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    margin = 14
    rect_box = [(margin, margin), (W - margin, H - margin)]
    
    # 1. Base Gradient Canvas
    bg_layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    bg_draw = ImageDraw.Draw(bg_layer)
    for y in range(margin, H - margin):
        t = (y - margin) / max(1, (H - 2 * margin))
        r = int(theme["bg_top"][0] * (1 - t) + theme["bg_bot"][0] * t)
        g = int(theme["bg_top"][1] * (1 - t) + theme["bg_bot"][1] * t)
        b = int(theme["bg_top"][2] * (1 - t) + theme["bg_bot"][2] * t)
        bg_draw.line([(margin, y), (W - margin, y)], fill=(r, g, b, 255))
        
    mask = Image.new("L", (W, H), 0)
    mask_draw = ImageDraw.Draw(mask)
    mask_draw.rounded_rectangle(rect_box, radius=24, fill=255)
    card_img.paste(bg_layer, (0, 0), mask)

    # 2. Cosmic / Holographic geometric laser lines & stadium flare
    grid_layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    g_draw = ImageDraw.Draw(grid_layer)
    for i in range(-200, W + 300, 36):
        g_draw.line([(i, margin), (i + 180, H - margin)], fill=(*theme["glow"], 22), width=1)
        g_draw.line([(i + 180, margin), (i, H - margin)], fill=(*theme["glow"], 22), width=1)
    
    if is_holo:
        # Radiant rainbow holographic foil shimmer lines across card
        rainbow_colors = [(255, 100, 100), (255, 200, 50), (100, 255, 150), (50, 220, 255), (200, 100, 255)]
        for idx, i in enumerate(range(-100, W + 200, 28)):
            c = rainbow_colors[idx % len(rainbow_colors)]
            g_draw.line([(i, margin), (i + 220, H - margin)], fill=(*c, 45), width=2)
    
    # Concentric orbital stadium glow circles
    g_draw.ellipse([W//2 - 180, H//2 - 200, W//2 + 180, H//2 + 160], outline=(*theme["primary"], 55), width=2)
    g_draw.ellipse([W//2 - 130, H//2 - 150, W//2 + 130, H//2 + 110], outline=(*theme["glow"], 85), width=2)
    card_img = Image.alpha_composite(card_img, grid_layer)
    draw = ImageDraw.Draw(card_img)

    # 3. Player Artwork / Real Match Moment Composite
    if is_mystery:
        sil_layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
        s_draw = ImageDraw.Draw(sil_layer)
        cx, cy = W // 2, H // 2 - 25
        s_draw.ellipse([cx - 110, cy - 110, cx + 110, cy + 110], fill=(12, 16, 28, 230), outline=(*theme["glow"], 180), width=3)
        s_draw.ellipse([cx - 125, cy - 125, cx + 125, cy + 125], outline=(*theme["primary"], 90), width=2)
        
        f_q = _get_nba_card_font(120, bold=True)
        s_draw.text((cx - 36, cy - 75), "?", fill=theme["border"], font=f_q)
        
        s_draw.rounded_rectangle([(cx - 160, cy + 85), (cx + 160, cy + 125)], radius=10, fill=(10, 14, 24, 240), outline=(*theme["primary"], 200), width=2)
        f_who = _get_nba_card_font(16, bold=True)
        s_draw.text((cx - 115, cy + 96), "WHO'S THAT 2K STAR?", fill=(255, 255, 255, 255), font=f_who)
        card_img = Image.alpha_composite(card_img, sil_layer)
        draw = ImageDraw.Draw(card_img)
    else:
        # 1. Try loading real match moment photo from local catalog
        action_photo = None
        if not headshot_img:
            action_photo = get_nba_player_moment_photo(card.get("name", ""), card=card)

        if not action_photo:
            if not headshot_img:
                headshot_img = get_nba_player_headshot(card.get("name", ""))
            if not headshot_img:
                # Load tier-specific hardcoded iconic Wikipedia match moment
                action_photo = get_tier_default_moment_image(tier_key)

        if action_photo:
            try:
                target_w, target_h = 480, 420
                aspect = action_photo.width / max(1, action_photo.height)
                if aspect > 1.15:
                    scale_h = target_h
                    scale_w = int(scale_h * aspect)
                else:
                    scale_w = target_w
                    scale_h = int(scale_w / aspect)
                p_scaled = action_photo.resize((scale_w, scale_h), Image.Resampling.LANCZOS)
                left = max(0, (p_scaled.width - target_w) // 2)
                top = max(0, (p_scaled.height - target_h) // 3)
                p_cropped = p_scaled.crop((left, top, left + target_w, top + target_h))
                
                p_cropped = ImageEnhance.Contrast(p_cropped).enhance(1.18)
                p_cropped = ImageEnhance.Color(p_cropped).enhance(1.22)
                
                # 4-way feathered vignette & bottom fade
                mask = Image.new("L", (target_w, target_h), 255)
                m_draw = ImageDraw.Draw(mask)
                for y in range(0, 45):
                    alpha = int(255 * (y / 45))
                    m_draw.line([(0, y), (target_w, y)], fill=alpha)
                fade_bot = 120
                for y in range(target_h - fade_bot, target_h):
                    alpha = int(255 * (1.0 - (y - (target_h - fade_bot)) / fade_bot))
                    m_draw.line([(0, y), (target_w, y)], fill=alpha)
                for x in range(0, 30):
                    alpha = int(255 * (x / 30))
                    for y in range(target_h):
                        cur = mask.getpixel((x, y))
                        mask.putpixel((x, y), min(cur, alpha))
                        mask.putpixel((target_w - 1 - x, y), min(cur, alpha))
                mask = mask.filter(ImageFilter.GaussianBlur(8))
                
                px = (W - target_w) // 2
                py = 70
                p_rgba = p_cropped.convert("RGBA")
                p_rgba.putalpha(mask)
                photo_layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
                photo_layer.paste(p_rgba, (px, py))
                card_img = Image.alpha_composite(card_img, photo_layer)
                draw = ImageDraw.Draw(card_img)
            except Exception:
                action_photo = None

        if not action_photo and headshot_img:
            try:
                # Enhance vibrancy & contrast for intense live match lighting
                enh_con = ImageEnhance.Contrast(headshot_img)
                p_enhanced = enh_con.enhance(1.18)
                enh_col = ImageEnhance.Color(p_enhanced)
                p_enhanced = enh_col.enhance(1.22)

                # Scale player to bold full card presence
                target_w = 460
                aspect = p_enhanced.height / max(1, p_enhanced.width)
                target_h = int(target_w * aspect)
                p_scaled = p_enhanced.resize((target_w, target_h), Image.Resampling.LANCZOS)

                # Tier Energy Aura Backlight behind player silhouette
                aura_layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
                a_draw = ImageDraw.Draw(aura_layer)
                cx, cy = W // 2, 280
                a_draw.ellipse([cx - 175, cy - 185, cx + 175, cy + 185], fill=(*theme["glow"], 50))
                a_draw.ellipse([cx - 130, cy - 140, cx + 130, cy + 140], fill=(*theme["primary"], 75))
                aura_layer = aura_layer.filter(ImageFilter.GaussianBlur(30))
                card_img = Image.alpha_composite(card_img, aura_layer)

                px = (W - p_scaled.width) // 2
                py = 85

                # Feathered bottom alpha mask: smooth fade into the stats dock
                p_rgba = p_scaled.convert("RGBA")
                p_mask = p_rgba.split()[3]
                
                fade_h = 110
                grad_fade = Image.new("L", (p_scaled.width, p_scaled.height), 255)
                gf_draw = ImageDraw.Draw(grad_fade)
                for gy in range(p_scaled.height - fade_h, p_scaled.height):
                    alpha_val = int(255 * (1.0 - (gy - (p_scaled.height - fade_h)) / fade_h))
                    gf_draw.line([(0, gy), (p_scaled.width, gy)], fill=alpha_val)
                
                final_mask = Image.composite(grad_fade, Image.new("L", p_mask.size, 0), p_mask)
                card_img.paste(p_rgba, (px, py), final_mask)
                draw = ImageDraw.Draw(card_img)
            except Exception:
                pass

    # 4. Top Ribbon Bar: Tier Edition
    draw.rounded_rectangle([(margin + 12, margin + 10), (W - margin - 12, margin + 40)], radius=8, fill=(10, 14, 24, 230), outline=(*theme["border"], 180), width=1)
    
    tier_title = f"🌟 FORGED HOLO FOIL • {card['ovr']} OVR PINNACLE" if is_holo else f"{theme['name'].upper()} EDITION"
    f_tier = _get_nba_card_font(11 if is_holo else 13, bold=True)
    t_w = len(tier_title) * 7
    draw.text((W // 2 - t_w // 2, margin + 16), tier_title, fill=(255, 220, 90, 255) if is_holo else theme["border"], font=f_tier)
    
    # Draw crisp gold stars on left and right of tier title
    _draw_star_polygon(draw, (W // 2 - t_w // 2 - 16, margin + 25), 6, (255, 215, 0, 255) if is_holo else (*theme["border"], 255))
    _draw_star_polygon(draw, (W // 2 + t_w // 2 + 16, margin + 25), 6, (255, 215, 0, 255) if is_holo else (*theme["border"], 255))

    # 5. Top-Left HUD: OVR & Position Shield
    ovr_box = [(margin + 12, margin + 48), (margin + 110, margin + 144)]
    draw.rounded_rectangle(ovr_box, radius=12, fill=(12, 16, 28, 245), outline=(255, 215, 0, 240) if is_holo else (*theme["glow"], 230), width=2)
    f_ovr = _get_nba_card_font(38, bold=True)
    draw.text((margin + 20, margin + 52), str(card["ovr"]), fill=(255, 215, 0, 255) if is_holo else (255, 255, 255, 255), font=f_ovr)
    f_ovr_lbl = _get_nba_card_font(11, bold=True)
    draw.text((margin + 74, margin + 63), "OVR", fill=(255, 215, 0, 255) if is_holo else theme["border"], font=f_ovr_lbl)
    
    draw.line([(margin + 20, margin + 104), (margin + 102, margin + 104)], fill=(*theme["primary"], 140), width=1)
    f_pos = _get_nba_card_font(18, bold=True)
    draw.text((margin + 36, margin + 112), card.get("pos", "SF"), fill=theme["glow"], font=f_pos)

    # 6. Top-Right HUD: Team Badge
    team_box = [(W - margin - 100, margin + 48), (W - margin - 12, margin + 112)]
    draw.rounded_rectangle(team_box, radius=12, fill=(12, 16, 28, 245), outline=(*theme["primary"], 180), width=2)
    f_team_lbl = _get_nba_card_font(10, bold=True)
    draw.text((W - margin - 82, margin + 54), "TEAM", fill=(148, 163, 184, 255), font=f_team_lbl)
    f_team = _get_nba_card_font(22, bold=True)
    draw.text((W - margin - 86, margin + 72), card.get("team", "NBA"), fill=(255, 255, 255, 255), font=f_team)

    # 7. Real-Life NBA Match Moment Banner
    if not is_mystery:
        moment_text = get_nba_card_moment(card)
        m_box = [(margin + 14, H - margin - 228), (W - margin - 14, H - margin - 198)]
        draw.rounded_rectangle(m_box, radius=8, fill=(12, 18, 32, 250), outline=(255, 215, 0, 230) if is_holo else (*theme["glow"], 220), width=1)
        
        # Left and right star accents
        _draw_star_polygon(draw, (margin + 26, H - margin - 213), 5, (255, 215, 0, 255) if is_holo else (*theme["glow"], 255))
        _draw_star_polygon(draw, (W - margin - 26, H - margin - 213), 5, (255, 215, 0, 255) if is_holo else (*theme["glow"], 255))
        
        full_moment_lbl = f"REAL NBA MOMENT: {moment_text.upper()}"
        font_sz = 10
        if len(full_moment_lbl) > 42:
            font_sz = 9
        if len(full_moment_lbl) > 50:
            font_sz = 8
        f_mom = _get_nba_card_font(font_sz, bold=True)
        draw.text((margin + 36, H - margin - 220 + (10 - font_sz)), full_moment_lbl, fill=(255, 225, 100, 255) if is_holo else theme["glow"], font=f_mom)

    # 8. Lower Card Info & Stats Deck
    lower_box = [(margin + 12, H - margin - 190), (W - margin - 12, H - margin - 14)]
    draw.rounded_rectangle(lower_box, radius=16, fill=(10, 14, 26, 250), outline=(255, 215, 0, 240) if is_holo else (*theme["border"], 220), width=2)
    
    name_display = "??? MYSTERY 2K STAR ???" if is_mystery else card["name"].upper()
    f_name = _get_nba_card_font(22 if is_mystery else 24, bold=True)
    draw.text((margin + 24, H - margin - 178), name_display, fill=(255, 215, 0, 255) if is_holo else (255, 255, 255, 255), font=f_name)
    
    sub_title = "Guess the player name in chat!" if is_mystery else f"{card.get('theme', 'Signature Series')} • {card.get('pos', 'SF')}/{card.get('sec_pos', 'SG')}"
    f_sub = _get_nba_card_font(12, bold=False)
    draw.text((margin + 24, H - margin - 148), sub_title, fill=(255, 225, 120, 255) if is_holo else theme["border"], font=f_sub)
    
    draw.line([(margin + 24, H - margin - 126), (W - margin - 24, H - margin - 126)], fill=(*theme["primary"], 120), width=1)
    
    stats_dict = card.get("stats", {"3pt": 90, "def": 90, "ath": 90, "clu": 90, "ins": 90, "ply": 90})
    stat_keys = [("3PT", stats_dict.get("3pt", 90)), ("DEF", stats_dict.get("def", 90)), 
                 ("ATH", stats_dict.get("ath", 90)), ("CLU", stats_dict.get("clu", 90))]
    
    stat_w = (W - 2 * margin - 60) // 4
    for idx, (s_lbl, s_val) in enumerate(stat_keys):
        sx = margin + 24 + idx * (stat_w + 8)
        sy = H - margin - 116
        draw.rounded_rectangle([(sx, sy), (sx + stat_w, sy + 44)], radius=8, fill=(18, 24, 40, 230), outline=(255, 215, 0, 180) if is_holo else (*theme["primary"], 120), width=1)
        
        f_slbl = _get_nba_card_font(10, bold=True)
        draw.text((sx + 8, sy + 6), s_lbl, fill=(255, 215, 0, 255) if is_holo else (148, 163, 184, 255), font=f_slbl)
        
        f_sval = _get_nba_card_font(16, bold=True)
        val_str = "??" if is_mystery else str(s_val)
        draw.text((sx + 8, sy + 22), val_str, fill=(255, 235, 130, 255) if is_holo else theme["glow"], font=f_sval)

    # Footer
    f_foot = _get_nba_card_font(9, bold=True)
    draw.text((margin + 24, H - margin - 38), "NBA 2K MOBILE • AUTHENTIC COLLECTIBLE", fill=(100, 116, 139, 255), font=f_foot)
    cid_str = f"CARD ID: {card.get('id', 'nba-2k')}"
    draw.text((W - margin - 24 - len(cid_str) * 6, H - margin - 38), cid_str, fill=(100, 116, 139, 255), font=f_foot)

    # 9. Outer Border Trim
    if is_holo:
        draw.rounded_rectangle(rect_box, radius=24, outline=(255, 215, 0, 255), width=4)
        holo_inner = [(margin + 4, margin + 4), (W - margin - 4, H - margin - 4)]
        draw.rounded_rectangle(holo_inner, radius=20, outline=(255, 230, 100, 230), width=2)
    else:
        draw.rounded_rectangle(rect_box, radius=24, outline=(*theme["border"], 255), width=3)
        inner_box = [(margin + 4, margin + 4), (W - margin - 4, H - margin - 4)]
        draw.rounded_rectangle(inner_box, radius=20, outline=(*theme["primary"], 120), width=1)

    buf = io.BytesIO()
    card_img.save(buf, format="PNG")
    buf.seek(0)
    return buf



def build_nbacard_embed(card: Dict[str, Any], copies_owned: int = 0, is_fav: bool = False, owner_user: Optional[discord.User] = None) -> discord.Embed:
    """Builds a full-detail NBA 2K Mobile inspection card embed with prominent tier details."""
    tier_info = NBA_2K_TIERS.get(card.get("tier", "gold"), NBA_2K_TIERS["gold"])
    moment = get_nba_card_moment(card)
    is_holo = bool(card.get("is_holo") or str(card.get("id", "")).startswith("holo_"))
    holo_badge = "🌟 [HOLO FOIL] " if is_holo else ""

    embed = discord.Embed(
        title=f"{tier_info['emoji']} {holo_badge}[{card['ovr']} OVR] {card['name'].upper()} • {card.get('pos', 'SF')} | {card.get('team', 'NBA')}",
        description=(
            f"### 🎴 **Tier:** {tier_info['emoji']} **{tier_info['name']}** (`{tier_info['ovr_range']} OVR`)\n"
            f"**Theme:** *{card.get('theme', 'Signature Series')}*\n"
            f"⚡ **Real-Life NBA Moment:** *{moment}*\n"
            f"💬 *\"{card.get('quote', '')}\"*\n"
        ),
        color=tier_info["color"]
    )
    
    stats = card.get("stats", {})
    pts_3 = stats.get("3pt", 80)
    defense = stats.get("def", 80)
    playmaking = stats.get("ply", 80)
    inside = stats.get("ins", 80)
    clutch = stats.get("clu", 80)
    ath = stats.get("ath", 80)
    
    embed.add_field(
        name="📊 2K Player Ratings & Attributes",
        value=(
            f"`🎯 3PT Shot `: [{format_stat_bar(pts_3)}] **{pts_3}**\n"
            f"`🔒 Defense  `: [{format_stat_bar(defense)}] **{defense}**\n"
            f"`🧠 Playmake `: [{format_stat_bar(playmaking)}] **{playmaking}**\n"
            f"`💥 Inside   `: [{format_stat_bar(inside)}] **{inside}**\n"
            f"`⚡ Clutch   `: [{format_stat_bar(clutch)}] **{clutch}**\n"
            f"`🏃 Athletic `: [{format_stat_bar(ath)}] **{ath}**"
        ),
        inline=False
    )
    
    badges = card.get("badges", [])
    if badges:
        embed.add_field(
            name="🏆 Signature Badges",
            value=" • ".join(f"`{b}`" for b in badges),
            inline=False
        )
        
    fav_indicator = " ⭐ **FAVORITE**" if is_fav else ""
    owner_str = f"Owner: **{owner_user.display_name}**" if owner_user else "Binder Inspection"
    quick_sell = card.get("quick_sell") or tier_info["quick_sell"]
    embed.add_field(
        name="📦 Inventory & Market Status",
        value=(
            f"• 🏷️ **Card Tier:** {tier_info['emoji']} **{tier_info['name']}**\n"
            f"• 🎴 **Card ID:** `{card['id']}`\n"
            f"• 📚 **Copies Owned:** `{copies_owned}`{fav_indicator}\n"
            f"• 💰 **Quick-Sell Value:** `💰 {quick_sell:,} VC`"
        ),
        inline=False
    )
    
    # Show other card versions available in the catalog for this player
    player_name_clean = card.get("name", "").replace(" (Holo Foil)", "").replace("🌟 ", "").strip()
    other_versions = [
        c for c in NBA_2K_MOBILE_CARDS
        if c["name"].lower() == player_name_clean.lower() and c["id"].lower() != card["id"].lower()
    ]
    if other_versions:
        lines = []
        for oc in other_versions:
            tinfo = NBA_2K_TIERS.get(oc["tier"], NBA_2K_TIERS["gold"])
            first_name = player_name_clean.split()[0].lower()
            tier_word = oc['tier'].replace('_', ' ')
            lines.append(f"• {tinfo['emoji']} **{tinfo['name']}** (`{oc['ovr']} OVR`): `!nbacard {first_name} {tier_word}`")
        embed.add_field(
            name=f"🔄 Other Card Tiers for {player_name_clean}",
            value="\n".join(lines),
            inline=False
        )
    
    embed.set_footer(text=f"NBA 2K Mobile Card Dex • Tier: {tier_info['name']} • {owner_str} • Card ID: {card['id']}")
    embed.timestamp = discord.utils.utcnow()
    return embed

def build_nbadex_embed(
    target_user: discord.User,
    cards_owned: List[Dict[str, Any]],
    tier_filter: Optional[str] = None,
    page: int = 1,
    page_size: int = 6,
    vc_balance: int = 1000
) -> Tuple[discord.Embed, int, List[Dict[str, Any]]]:
    """Builds a paginated collection binder embed for a user."""
    owned_counts: Dict[str, int] = {}
    fav_status: Dict[str, bool] = {}
    for entry in cards_owned:
        cid = entry["card_id"].lower()
        owned_counts[cid] = owned_counts.get(cid, 0) + 1
        if entry.get("is_favorite"):
            fav_status[cid] = True
            
    resolved_owned_cards = []
    for cid, count in owned_counts.items():
        card_obj = get_nba_card(cid)
        if card_obj:
            resolved_owned_cards.append({**card_obj, "copies": count, "is_fav": fav_status.get(cid, False)})
            
    resolved_owned_cards.sort(key=lambda x: (x["ovr"], x["name"]), reverse=True)
    
    if tier_filter and tier_filter != "all":
        filtered_cards = [c for c in resolved_owned_cards if c["tier"] == tier_filter]
    else:
        filtered_cards = resolved_owned_cards
        
    total_catalog = len(NBA_2K_MOBILE_CARDS)
    unique_owned = len(resolved_owned_cards)
    percent_complete = (unique_owned / total_catalog * 100.0) if total_catalog > 0 else 0.0
    total_power = sum(c["ovr"] * c["copies"] for c in resolved_owned_cards)
    
    tier_counts = {t: 0 for t in NBA_2K_TIERS}
    for c in resolved_owned_cards:
        t = c.get("tier", "gold")
        tier_counts[t] = tier_counts.get(t, 0) + c["copies"]
        
    total_items = len(filtered_cards)
    total_pages = max(1, (total_items + page_size - 1) // page_size)
    page = max(1, min(page, total_pages))
    
    start_idx = (page - 1) * page_size
    page_cards = filtered_cards[start_idx : start_idx + page_size]
    
    filter_label = NBA_2K_TIERS.get(tier_filter, {}).get("name", "All Tiers") if tier_filter and tier_filter != "all" else "All Tiers"
    
    embed = discord.Embed(
        title=f"🎴 {target_user.display_name}'s NBA 2K Mobile Dex",
        description=(
            f"**Progress:** `{unique_owned}/{total_catalog}` cards (`{percent_complete:.1f}%`)\n"
            f"**Total Power:** `⚡ {total_power:,} OVR` | **Wallet:** `💰 {vc_balance:,} VC`\n"
            f"**Tier Breakdown:** "
            f"🌌 `{tier_counts['dark_matter']}` • "
            f"✨ `{tier_counts['galaxy_opal']}` • "
            f"💎 `{tier_counts['diamond']}` • "
            f"🔮 `{tier_counts['amethyst']}` • "
            f"🔴 `{tier_counts['ruby']}` • "
            f"🟡 `{tier_counts['gold']}`\n"
            f"─────────────────────────────\n"
            f"🔍 **Filter:** `{filter_label}` ({total_items} cards)\n"
        ),
        color=discord.Color.gold()
    )
    
    if not page_cards:
        embed.add_field(
            name="Empty Binder Page",
            value="No cards found in this filter! Open packs with `/openpack` or claim chat drops.",
            inline=False
        )
    else:
        for card in page_cards:
            t_info = NBA_2K_TIERS.get(card["tier"], NBA_2K_TIERS["gold"])
            fav_star = " ⭐" if card.get("is_fav") else ""
            dup_tag = f" `[x{card['copies']}]`" if card['copies'] > 1 else ""
            stats = card.get("stats", {})
            embed.add_field(
                name=f"{t_info['emoji']} [{card['ovr']}] {card['name']} • {card['pos']} ({card['team']}){fav_star}{dup_tag}",
                value=(
                    f"*{card['theme']}* — ID: `{card['id']}`\n"
                    f"`3PT: {stats.get('3pt', 80)}` • `DEF: {stats.get('def', 80)}` • `PLY: {stats.get('ply', 80)}` • `INS: {stats.get('ins', 80)}` • `CLU: {stats.get('clu', 80)}`"
                ),
                inline=False
            )
            
    embed.set_footer(text=f"Page {page}/{total_pages} • Use dropdown below to inspect a card • Total Cards: {sum(c['copies'] for c in resolved_owned_cards)}")
    embed.timestamp = discord.utils.utcnow()
    return embed, total_pages, page_cards

def _build_odds_lines(pack_data: Dict[str, Any]) -> str:
    """Returns a formatted string of pull odds for a pack."""
    odds = pack_data.get("odds", {})
    tier_order = ["dark_matter", "galaxy_opal", "diamond", "amethyst", "ruby", "gold"]
    lines = []
    for tier_key in tier_order:
        if tier_key in odds:
            t_info = NBA_2K_TIERS.get(tier_key, {})
            emoji = t_info.get("emoji", "•")
            name = t_info.get("short_name", tier_key.replace("_", " ").title())
            ovr = t_info.get("ovr_range", "??")
            pct = odds[tier_key] * 100
            # Build a simple visual bar (5 chars = 100%)
            bar_filled = max(1, round(pct / 10))
            bar = "▰" * bar_filled + "▱" * (10 - bar_filled)
            lines.append(f"{emoji} **{name}** (`{ovr} OVR`) — `{bar}` **{pct:.0f}%**")
    return "\n".join(lines) if lines else "No odds data available."


def build_pack_shop_embed(vc_balance: int) -> discord.Embed:
    """Builds the full NBA 2K Mobile Card Shop embed with transparent per-pack drop rates."""
    embed = discord.Embed(
        title="📦 NBA 2K Mobile Card Packs Shop",
        description=(
            f"**Your VC Balance:** `💰 {vc_balance:,} VC`\n\n"
            f"Select a pack below to buy and rip open!\n"
            f"All pull rates are **100% transparent and honest** — no hidden odds.\n"
        ),
        color=discord.Color.gold()
    )

    for pack_id, pack_data in NBA_PACK_TYPES.items():
        cost = pack_data["cost"]
        name = pack_data["name"]
        desc = pack_data.get("description", "")
        can_afford = "✅" if vc_balance >= cost else "❌"
        odds_text = _build_odds_lines(pack_data)
        embed.add_field(
            name=f"{can_afford} {name} — `{cost:,} VC`",
            value=f"*{desc}*\n{odds_text}",
            inline=False
        )

    embed.set_footer(text="Pull rates shown are exact probabilities • Use !packodds to view anytime")
    embed.timestamp = discord.utils.utcnow()
    return embed


def build_openpack_embed(user: discord.User, pack_data: Dict[str, Any], card: Dict[str, Any], new_vc: int, is_new: bool = True, copies: int = 1) -> discord.Embed:
    """Builds an authentic 2K Mobile pack reveal embed with transparent drop rates."""
    tier_info = NBA_2K_TIERS.get(card["tier"], NBA_2K_TIERS["gold"])
    moment = get_nba_card_moment(card)
    status_str = "🌟 **NEW CARD ADDED TO BINDER!**" if is_new else f"🔄 **DUPLICATE COPY OBTAINED (Now x{copies})**"
    
    embed = discord.Embed(
        title=f"{tier_info['emoji']} 2K MOBILE PACK REVEAL • [{card['ovr']} OVR] {card['name'].upper()}!",
        description=(
            f"# {tier_info['emoji']} {tier_info['name'].upper()} PULL!\n"
            f"**{user.mention} opened a {pack_data['name']}!**\n\n"
            f"{status_str}\n\n"
            f"**Player:** `{card['name']}` • **Pos:** `{card['pos']}` • **Team:** `{card['team']}`\n"
            f"⚡ **Real NBA Moment:** *{moment}*\n"
            f"**Theme:** *{card['theme']}*\n"
            f"*{card.get('quote', '')}*"
        ),
        color=tier_info["color"]
    )
    
    stats = card.get("stats", {})
    embed.add_field(
        name="📊 Ratings Breakdown",
        value=(
            f"`🎯 3PT `: **{stats.get('3pt', 80)}** | `🔒 DEF `: **{stats.get('def', 80)}** | `🧠 PLY `: **{stats.get('ply', 80)}**\n"
            f"`💥 INS `: **{stats.get('ins', 80)}** | `⚡ CLU `: **{stats.get('clu', 80)}** | `🏃 ATH `: **{stats.get('ath', 80)}**"
        ),
        inline=False
    )
    
    badges = card.get("badges", [])
    if badges:
        embed.add_field(name="🏆 Badges", value=" • ".join(f"`{b}`" for b in badges[:4]), inline=False)
        
    embed.add_field(
        name="💰 Virtual Currency Wallet",
        value=f"• **Remaining Balance:** `💰 {new_vc:,} VC`\n• **Quick-Sell Value:** `💰 {tier_info['quick_sell']:,} VC`",
        inline=False
    )

    # Transparent drop odds for this pack
    embed.add_field(
        name=f"🎲 {pack_data['name']} Pull Rates (Fully Transparent)",
        value=_build_odds_lines(pack_data),
        inline=False
    )
    
    # Use the verified player-specific Wikimedia moment photo URL
    is_holo = bool(card.get("is_holo") or str(card.get("id", "")).startswith("holo_"))
    cid = str(card.get("id", "")).lower().replace("holo_", "").replace("holo-", "").strip()
    pname = card.get("name", "").replace("🌟", "").replace("(Holo Foil)", "").replace("(Holo)", "").replace("(Foil)", "").strip()
    norm_p = unicodedata.normalize('NFKD', pname).encode('ascii', 'ignore').decode('utf-8').lower().replace(".", "").replace("'", "").strip()
    
    verified_url = (
        (NBA_HOLO_EDITION_MOMENT_URLS.get(cid) if is_holo else None)
        or NBA_CARD_SPECIFIC_MOMENT_URLS.get(cid)
        or NBA_PLAYER_MOMENT_ACTION_URLS.get(pname.lower().strip())
        or NBA_PLAYER_MOMENT_ACTION_URLS.get(norm_p)
    )
    if verified_url:
        embed.set_image(url=verified_url.split("?")[0])

        
    embed.set_footer(text=f"NBA 2K Mobile Pack Opening • Card ID: {card['id']} • Odds always shown honestly")
    embed.timestamp = discord.utils.utcnow()
    return embed

def build_multi_trade_embed(
    sender_user: discord.User,
    target_user: discord.User,
    cards_a: List[Dict[str, Any]],
    cards_b: List[Dict[str, Any]],
    sender_ready: bool = False,
    target_ready: bool = False,
    status: str = "pending",
    countdown_secs: Optional[int] = None,
    vc_a: int = 0,
    vc_b: int = 0
) -> discord.Embed:
    """Builds a multi-card & VC live trading floor embed with real-time status and countdown."""
    if status == "accepted":
        title = "🤝 NBA 2K Mobile Trade Completed!"
        desc = f"🎉 **The trade between {sender_user.mention} and {target_user.mention} has been successfully processed!**"
        color = discord.Color.green()
    elif status == "declined":
        title = "❌ NBA 2K Mobile Trade Cancelled / Declined"
        desc = f"The trade proposal between {sender_user.mention} and {target_user.mention} was cancelled or declined."
        color = discord.Color.red()
    elif status == "countdown":
        title = f"🔒 TRADE LOCKED — EXECUTING IN {countdown_secs}s"
        desc = (
            f"⚠️ **Both players accepted! Final 7-second review window.**\n"
            f"Trade will automatically finalize in **`{countdown_secs}` seconds**.\n"
            f"*Click `Cancel / Decline` at any time to abort!*"
        )
        color = discord.Color.gold()
    else:
        title = "🏀 NBA 2K Mobile Live Trading Floor"
        desc = (
            f"**{sender_user.mention}** has opened a live trade session with **{target_user.mention}**!\n"
            f"• Both players can offer up to **5 cards** and send **VC** with `➕ Offer Card` & `💰 Offer VC`\n"
            f"• Once both click **`Ready`**, a **7-second safety countdown** will lock and execute the trade."
        )
        color = discord.Color.blue()

    embed = discord.Embed(title=title, description=desc, color=color)

    # Sender Offer Field
    ready_tag_a = "🟢 **READY**" if sender_ready else "⏳ *Selecting...*"
    if status in ("accepted", "countdown"):
        ready_tag_a = "🔒 **LOCKED**"

    lines_a = []
    total_ovr_a = 0
    for idx, c in enumerate(cards_a, 1):
        t = NBA_2K_TIERS.get(c.get("tier", "gold"), NBA_2K_TIERS["gold"])
        ovr = c.get("ovr", 80)
        total_ovr_a += ovr
        lines_a.append(f"`{idx}.` {t['emoji']} **[{ovr} OVR] {c['name']}** (`{c.get('pos', 'SF')}` · `{c.get('team', 'NBA')}`)")
    
    val_a = "\n".join(lines_a) if lines_a else "*No cards placed on table yet.*"
    if vc_a > 0:
        val_a += f"\n💰 **Offered VC:** `+{vc_a:,} VC`"
    val_a += f"\n\n**Status:** {ready_tag_a}"
    if cards_a:
        val_a += f" | **Power:** `⚡ {total_ovr_a} OVR`"

    vc_header_a = f" | 💰 {vc_a:,} VC" if vc_a > 0 else ""
    embed.add_field(
        name=f"📤 {sender_user.display_name}'s Offer ({len(cards_a)}/5 cards{vc_header_a})",
        value=val_a,
        inline=True
    )

    # Target Offer Field
    ready_tag_b = "🟢 **READY**" if target_ready else "⏳ *Selecting...*"
    if status in ("accepted", "countdown"):
        ready_tag_b = "🔒 **LOCKED**"

    lines_b = []
    total_ovr_b = 0
    for idx, c in enumerate(cards_b, 1):
        t = NBA_2K_TIERS.get(c.get("tier", "gold"), NBA_2K_TIERS["gold"])
        ovr = c.get("ovr", 80)
        total_ovr_b += ovr
        lines_b.append(f"`{idx}.` {t['emoji']} **[{ovr} OVR] {c['name']}** (`{c.get('pos', 'SF')}` · `{c.get('team', 'NBA')}`)")

    val_b = "\n".join(lines_b) if lines_b else "*No cards placed on table yet.*"
    if vc_b > 0:
        val_b += f"\n💰 **Offered VC:** `+{vc_b:,} VC`"
    val_b += f"\n\n**Status:** {ready_tag_b}"
    if cards_b:
        val_b += f" | **Power:** `⚡ {total_ovr_b} OVR`"

    vc_header_b = f" | 💰 {vc_b:,} VC" if vc_b > 0 else ""
    embed.add_field(
        name=f"📥 {target_user.display_name}'s Offer ({len(cards_b)}/5 cards{vc_header_b})",
        value=val_b,
        inline=True
    )

    embed.set_footer(text="NBA 2K Mobile Multi-Card & VC Trading Engine • 7-Second Safety Lock")
    embed.timestamp = discord.utils.utcnow()
    return embed


def build_trade_embed(sender_user: discord.User, target_user: discord.User, card_a: Dict[str, Any], card_b: Dict[str, Any], status: str = "pending") -> discord.Embed:
    """Backwards compatibility wrapper for single card trades."""
    list_a = [card_a] if card_a else []
    list_b = [card_b] if card_b else []
    return build_multi_trade_embed(sender_user, target_user, list_a, list_b, status=status)

def build_nba_drop_embed(card: Dict[str, Any], hint_level: int = 1, spawner: Optional[Union[discord.Member, discord.User]] = None) -> discord.Embed:
    """Builds a clean, concise mystery card drop embed."""
    tier_info = NBA_2K_TIERS.get(card["tier"], NBA_2K_TIERS["gold"])
    hint_str = generate_player_hint(card["name"], hint_level)
    host_line = f"\n• 👑 **Hosted By:** {spawner.mention} *(Host disqualified from catching)*" if spawner else ""
    footer_text = "NBA 2K Mobile Spawns • First to guess catches card + 150 VC! • Event host cannot claim" if spawner else "NBA 2K Mobile Spawns • First to guess catches the card + 150 VC!"
    embed = discord.Embed(
        title="🏀 A wild NBA 2K card appeared!" if not spawner else f"🏀 Special NBA Card Drop Hosted by {spawner.display_name}!",
        description=(
            f"Guess the player name to catch this card!\n\n"
            f"• **Type:** `!catch <name>` or guess in chat\n"
            f"• **Tier:** {tier_info['emoji']} **{tier_info['name']}**\n"
            f"• **Position:** `{card['pos']}` | **Team:** `{card['team']}`\n"
            f"• **Hint:** `{hint_str}`"
            f"{host_line}"
        ),
        color=tier_info["color"]
    )
    embed.set_image(url="attachment://nba_card.png")
    embed.set_footer(text=footer_text)
    embed.timestamp = discord.utils.utcnow()
    return embed

def build_catch_success_embed(user: discord.User, card: Dict[str, Any], new_bal: int, copies: int) -> discord.Embed:
    """Builds a concise, clean catch success embed."""
    tier_info = NBA_2K_TIERS.get(card["tier"], NBA_2K_TIERS["gold"])
    moment = get_nba_card_moment(card)
    embed = discord.Embed(
        title=f"🏀 {tier_info['emoji']} Card Caught by {user.display_name}!",
        description=(
            f"🎉 {user.mention} guessed correctly and caught **[{card['ovr']} OVR] {card['name']}**!\n\n"
            f"⚡ **Real NBA Moment:** *{moment}*\n"
            f"• **Tier:** {tier_info['emoji']} **{tier_info['name']}** | **Team:** `{card['team']}` (`{card['pos']}`)\n"
            f"• **Reward:** `+150 VC` (Balance: `💰 {new_bal:,} VC`)\n"
            f"• **Collection:** You now own `{copies}` copies of this card!"
        ),
        color=tier_info["color"]
    )
    embed.set_image(url="attachment://nba_card.png")
    embed.set_footer(text=f"Card ID: {card['id']} • View in binder: !nbadex")
    embed.timestamp = discord.utils.utcnow()
    return embed


async def spawn_nba_card_drop(
    channel: discord.TextChannel,
    requested_tier: Optional[str] = None,
    spawner: Optional[Union[discord.Member, discord.User]] = None
) -> Optional[discord.Message]:
    """Spawns an authentic NBA 2K Mobile wild card drop with card graphic in the specified text channel."""
    now_drop_ts = time.time()
    if requested_tier and requested_tier.lower() in NBA_2K_TIERS:
        t_key = requested_tier.lower()
        tier_pool = [c for c in NBA_2K_MOBILE_CARDS if c["tier"] == t_key]
    else:
        drop_tier = random.choices(
            ["gold", "ruby", "amethyst", "diamond", "galaxy_opal"],
            weights=[0.55, 0.25, 0.12, 0.06, 0.02],
            k=1
        )[0]
        tier_pool = [c for c in NBA_2K_MOBILE_CARDS if c["tier"] == drop_tier]
    if not tier_pool:
        tier_pool = NBA_2K_MOBILE_CARDS

    drop_card = random.choice(tier_pool)
    drop_id = f"{channel.guild.id}_{int(now_drop_ts)}"
    drop_info = {
        "card": drop_card,
        "claimed": False,
        "drop_id": drop_id,
        "channel_id": channel.id,
        "guild_id": channel.guild.id,
        "spawned_at": now_drop_ts,
        "hints_used": 1,
        "spawner_id": spawner.id if spawner else None,
        "spawner_name": spawner.display_name if spawner else None
    }
    _active_nba_drops[channel.id] = drop_info
    _active_nba_drops[channel.guild.id] = drop_info
    
    # Generate mystery card graphic
    card_buf = generate_nba_card_graphic(drop_card, is_mystery=True)
    card_file = discord.File(fp=card_buf, filename="nba_card.png")
    
    drop_embed = build_nba_drop_embed(drop_card, 1, spawner=spawner)
    drop_view = NBAChatDropView(drop_card, drop_id, channel.id)
    drop_msg = await channel.send(embed=drop_embed, file=card_file, view=drop_view)
    drop_info["message"] = drop_msg
    return drop_msg


# ── Discord UI Views ─────────────────────────────────────────────────────────

class TierFilterSelect(discord.ui.Select):
    def __init__(self, current_tier: Optional[str] = None):
        options = [
            discord.SelectOption(label="All Tiers (Full Dex)", value="all", emoji="🎴", default=(current_tier in [None, "all"])),
            discord.SelectOption(label="Dark Matter / G.O.A.T. (99 OVR)", value="dark_matter", emoji="🌌", default=(current_tier == "dark_matter")),
            discord.SelectOption(label="Galaxy Opal (97-98 OVR)", value="galaxy_opal", emoji="✨", default=(current_tier == "galaxy_opal")),
            discord.SelectOption(label="Diamond (93-96 OVR)", value="diamond", emoji="💎", default=(current_tier == "diamond")),
            discord.SelectOption(label="Amethyst (88-92 OVR)", value="amethyst", emoji="🔮", default=(current_tier == "amethyst")),
            discord.SelectOption(label="Ruby (84-87 OVR)", value="ruby", emoji="🔴", default=(current_tier == "ruby")),
            discord.SelectOption(label="Gold (75-83 OVR)", value="gold", emoji="🟡", default=(current_tier == "gold")),
        ]
        super().__init__(placeholder="🔍 Filter Collection by Tier...", min_values=1, max_values=1, options=options, row=0)

    async def callback(self, interaction: discord.Interaction):
        try:
            view: NBADexView = self.view
            if interaction.user.id != view.author.id:
                await interaction.response.send_message("❌ This is not your binder session.", ephemeral=True)
                return
            view.tier_filter = self.values[0]
            view.page = 1
            await view.refresh_message(interaction)
        except Exception as e:
            logger.error(f"Error in TierFilterSelect callback: {e}")
            if not interaction.response.is_done():
                await interaction.response.send_message(f"❌ Error: {e}", ephemeral=True)


class CardInspectSelect(discord.ui.Select):
    def __init__(self, page_cards: List[Dict[str, Any]]):
        options = []
        for c in page_cards[:25]:
            t_info = NBA_2K_TIERS.get(c.get("tier"), NBA_2K_TIERS["gold"])
            fav_tag = "⭐ " if c.get("is_fav") else ""
            dup_tag = f" (x{c['copies']})" if c.get("copies", 1) > 1 else ""
            options.append(
                discord.SelectOption(
                    label=f"{fav_tag}[{c['ovr']}] {c['name']}{dup_tag}"[:100],
                    value=c["id"],
                    description=f"{c['pos']} • {c['team']} • {c['theme']}"[:100],
                    emoji=t_info["emoji"]
                )
            )
        if not options:
            options.append(discord.SelectOption(label="No cards on this page", value="none"))
        super().__init__(placeholder="🔍 Select a card to inspect full stats & art...", min_values=1, max_values=1, options=options, row=1)

    async def callback(self, interaction: discord.Interaction):
        try:
            val = self.values[0]
            if val == "none":
                await interaction.response.send_message("No card selected.", ephemeral=True)
                return
            card = get_nba_card(val)
            if not card:
                await interaction.response.send_message("❌ Card not found.", ephemeral=True)
                return
            view: NBADexView = self.view
            # Find copies and fav status from view cards
            copies = 0
            is_fav = False
            for entry in view.cards_owned:
                if entry["card_id"].lower() == card["id"].lower():
                    copies += 1
                    if entry.get("is_favorite"):
                        is_fav = True
            embed = build_nbacard_embed(card, copies_owned=copies, is_fav=is_fav, owner_user=view.target_user)
            inspect_view = NBACardInspectView(card, view.target_user, copies, is_fav, author=interaction.user, parent_dex_view=view)
            await interaction.response.send_message(embed=embed, view=inspect_view, ephemeral=True)
        except Exception as e:
            logger.error(f"Error in CardInspectSelect callback: {e}")
            if not interaction.response.is_done():
                await interaction.response.send_message(f"❌ Error: {e}", ephemeral=True)


class NBADexView(discord.ui.View):
    def __init__(self, author: discord.User, target_user: discord.User, cards_owned: List[Dict[str, Any]], tier_filter: Optional[str] = "all", page: int = 1, vc_balance: int = 1000, is_private: bool = False):
        super().__init__(timeout=180.0)
        self.author = author
        self.target_user = target_user
        self.cards_owned = cards_owned
        self.tier_filter = tier_filter or "all"
        self.page = page
        self.vc_balance = vc_balance
        self.is_private = is_private
        self.total_pages = 1
        self.page_cards: List[Dict[str, Any]] = []
        self._build_components()

    def _build_components(self):
        self.clear_items()
        # Embed calculations to know total pages & page cards
        _, total_pages, page_cards = build_nbadex_embed(
            self.target_user, self.cards_owned, self.tier_filter, self.page, 6, self.vc_balance
        )
        self.total_pages = total_pages
        self.page_cards = page_cards

        # Row 0: Tier Filter
        self.add_item(TierFilterSelect(self.tier_filter))
        # Row 1: Card Inspect Dropdown (if page has cards)
        if self.page_cards:
            self.add_item(CardInspectSelect(self.page_cards))

        # Row 2: Nav Buttons
        first_btn = discord.ui.Button(emoji="⏮️", style=discord.ButtonStyle.secondary, disabled=(self.page <= 1), row=2)
        first_btn.callback = self.first_page
        self.add_item(first_btn)

        prev_btn = discord.ui.Button(emoji="◀️", style=discord.ButtonStyle.secondary, disabled=(self.page <= 1), row=2)
        prev_btn.callback = self.prev_page
        self.add_item(prev_btn)

        page_btn = discord.ui.Button(label=f"Page {self.page}/{self.total_pages}", style=discord.ButtonStyle.primary, disabled=True, row=2)
        self.add_item(page_btn)

        next_btn = discord.ui.Button(emoji="▶️", style=discord.ButtonStyle.secondary, disabled=(self.page >= self.total_pages), row=2)
        next_btn.callback = self.next_page
        self.add_item(next_btn)

        last_btn = discord.ui.Button(emoji="⏭️", style=discord.ButtonStyle.secondary, disabled=(self.page >= self.total_pages), row=2)
        last_btn.callback = self.last_page
        self.add_item(last_btn)

        # Row 3: Action Buttons
        pack_btn = discord.ui.Button(label="📦 Buy Pack", style=discord.ButtonStyle.success, emoji="📦", row=3)
        pack_btn.callback = self.quick_pack
        self.add_item(pack_btn)

        daily_btn = discord.ui.Button(label="💰 Daily VC", style=discord.ButtonStyle.secondary, emoji="💰", row=3)
        daily_btn.callback = self.claim_daily
        self.add_item(daily_btn)

        # Collection Privacy Toggle Button (when viewing your own dex)
        if self.target_user.id == self.author.id:
            priv_label = "🔒 Private" if self.is_private else "🌐 Public"
            priv_style = discord.ButtonStyle.secondary if self.is_private else discord.ButtonStyle.primary
            priv_btn = discord.ui.Button(label=priv_label, style=priv_style, emoji="🔒" if self.is_private else "🌐", row=3)
            priv_btn.callback = self.toggle_privacy
            self.add_item(priv_btn)

        close_btn = discord.ui.Button(label="Close", style=discord.ButtonStyle.danger, emoji="✖️", row=3)
        close_btn.callback = self.close_session
        self.add_item(close_btn)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("❌ This is not your binder session. Open yours with `/nbadex`.", ephemeral=True)
            return False
        return True

    async def toggle_privacy(self, interaction: discord.Interaction):
        try:
            new_state = await db.toggle_user_nba_privacy(self.author.id)
            self.is_private = new_state
            status_tag = "🔒 **PRIVATE**" if new_state else "🌐 **PUBLIC**"
            expl = (
                "Other members cannot inspect your collection binder with `/nbadex`."
                if new_state else
                "Other members can now view your collection binder with `/nbadex`."
            )
            await interaction.response.send_message(
                f"🛡️ **Collection Privacy Updated!**\nYour NBA Card Binder & Dex is now {status_tag}.\n💡 {expl}",
                ephemeral=True
            )
            await self.refresh_message(interaction)
        except Exception as e:
            logger.error(f"Error toggling binder privacy: {e}")
            if not interaction.response.is_done():
                await interaction.response.send_message(f"❌ Error: {e}", ephemeral=True)

    async def refresh_message(self, interaction: discord.Interaction):
        self.cards_owned = await db.get_user_nba_cards(self.target_user.id)
        self.vc_balance = await db.get_user_vc(self.target_user.id)
        self.is_private = await db.get_user_nba_privacy(self.target_user.id)
        embed, _, _ = build_nbadex_embed(
            self.target_user, self.cards_owned, self.tier_filter, self.page, 6, self.vc_balance
        )
        self._build_components()
        if not interaction.response.is_done():
            await interaction.response.edit_message(embed=embed, view=self)
        else:
            await interaction.message.edit(embed=embed, view=self)

    async def first_page(self, interaction: discord.Interaction):
        self.page = 1
        await self.refresh_message(interaction)

    async def prev_page(self, interaction: discord.Interaction):
        self.page = max(1, self.page - 1)
        await self.refresh_message(interaction)

    async def next_page(self, interaction: discord.Interaction):
        self.page = min(self.total_pages, self.page + 1)
        await self.refresh_message(interaction)

    async def last_page(self, interaction: discord.Interaction):
        self.page = self.total_pages
        await self.refresh_message(interaction)

    async def quick_pack(self, interaction: discord.Interaction):
        embed = build_pack_shop_embed(self.vc_balance)
        pack_view = QuickPackSelectView(self.author)
        await interaction.response.send_message(embed=embed, view=pack_view, ephemeral=True)

    async def claim_daily(self, interaction: discord.Interaction):
        success, new_bal, rem = await db.claim_nba_daily(self.author.id, 1000)
        if success:
            await interaction.response.send_message(
                f"🎉 **Daily Reward Claimed!** +1,000 VC has been added to your wallet!\n💰 **New Balance:** `{new_bal:,} VC`",
                ephemeral=True
            )
            self.vc_balance = new_bal
            await self.refresh_message(interaction)
        else:
            hours = int(rem // 3600)
            minutes = int((rem % 3600) // 60)
            await interaction.response.send_message(
                f"⏳ **Daily VC Cooldown:** You can claim your next daily reward in **{hours}h {minutes}m**.\n💰 **Current Balance:** `{new_bal:,} VC`",
                ephemeral=True
            )

    async def close_session(self, interaction: discord.Interaction):
        self.stop()
        await interaction.message.delete()


class QuickPackSelectView(discord.ui.View):
    def __init__(self, author: discord.User):
        super().__init__(timeout=60.0)
        self.author = author

    @discord.ui.button(label="Starter Pack (250 VC)", style=discord.ButtonStyle.primary, emoji="📦", row=0)
    async def open_starter(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._open(interaction, "starter")

    @discord.ui.button(label="Standard Pack (750 VC)", style=discord.ButtonStyle.primary, emoji="🏀", row=0)
    async def open_standard(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._open(interaction, "standard")

    @discord.ui.button(label="All-Star Pack (1,500 VC)", style=discord.ButtonStyle.success, emoji="⭐", row=0)
    async def open_allstar(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._open(interaction, "allstar")

    @discord.ui.button(label="HOF Elite Pack (3,000 VC)", style=discord.ButtonStyle.secondary, emoji="🏆", row=1)
    async def open_hof(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._open(interaction, "hof")

    @discord.ui.button(label="G.O.A.T. Pack (5,000 VC)", style=discord.ButtonStyle.danger, emoji="🐐", row=1)
    async def open_goat(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._open(interaction, "goat")

    async def _open(self, interaction: discord.Interaction, pack_id: str):
        pack_data = NBA_PACK_TYPES.get(pack_id, NBA_PACK_TYPES["starter"])
        cost = pack_data["cost"]
        bal = await db.get_user_vc(interaction.user.id)
        if bal < cost:
            await interaction.response.send_message(
                f"❌ **Insufficient VC!** You need `💰 {cost:,} VC` for {pack_data['name']}, but you only have `💰 {bal:,} VC`.\n"
                f"• Claim daily VC with `/nbadaily`\n"
                f"• Quick-sell duplicate cards with `/nbasell`\n"
                f"• Claim wild chat drops on the court!",
                ephemeral=True
            )
            return

        deducted = await db.deduct_user_vc(interaction.user.id, cost)
        if not deducted:
            await interaction.response.send_message("❌ Failed to process VC transaction. Please try again.", ephemeral=True)
            return

        card = roll_pack_card(pack_id, interaction.user.id)
        existing_cards = await db.get_user_nba_cards(interaction.user.id)
        existing_cids = [c["card_id"].lower() for c in existing_cards]
        is_new = card["id"].lower() not in existing_cids
        copies_now = existing_cids.count(card["id"].lower()) + 1

        await db.add_user_nba_card(interaction.user.id, card["id"], source=f"pack_{pack_id}")
        new_bal = await db.get_user_vc(interaction.user.id)

        embed = build_openpack_embed(interaction.user, pack_data, card, new_bal, is_new=is_new, copies=copies_now)
        reveal_view = NBAPackOpenView(interaction.user, pack_id, card, new_bal, is_new, copies_now)
        try:
            card_buf = generate_nba_card_graphic(card, is_mystery=False)
            card_file = discord.File(fp=card_buf, filename="nba_card.png")
            await interaction.response.send_message(embed=embed, file=card_file, view=reveal_view)
        except Exception:
            await interaction.response.send_message(embed=embed, view=reveal_view)


class NBAPackOpenView(discord.ui.View):
    def __init__(self, user: discord.User, pack_id: str, card: Dict[str, Any], new_bal: int, is_new: bool, copies: int):
        super().__init__(timeout=120.0)
        self.user = user
        self.pack_id = pack_id
        self.card = card
        self.new_bal = new_bal
        self.is_new = is_new
        self.copies = copies

        pack_data = NBA_PACK_TYPES.get(pack_id, NBA_PACK_TYPES["starter"])
        self.open_another_btn = discord.ui.Button(
            label=f"Open Another ({pack_data['cost']:,} VC)",
            style=discord.ButtonStyle.success,
            emoji="📦",
            row=0
        )
        self.open_another_btn.callback = self.open_another
        self.add_item(self.open_another_btn)

        self.dex_btn = discord.ui.Button(label="View in Binder", style=discord.ButtonStyle.primary, emoji="🎴", row=0)
        self.dex_btn.callback = self.view_in_dex
        self.add_item(self.dex_btn)

        self.inspect_btn = discord.ui.Button(label="Inspect Card", style=discord.ButtonStyle.secondary, emoji="🔍", row=0)
        self.inspect_btn.callback = self.inspect_pulled_card
        self.add_item(self.inspect_btn)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.user.id:
            await interaction.response.send_message("❌ This pack opening session belongs to someone else.", ephemeral=True)
            return False
        return True

    async def open_another(self, interaction: discord.Interaction):
        pack_data = NBA_PACK_TYPES.get(self.pack_id, NBA_PACK_TYPES["starter"])
        cost = pack_data["cost"]
        bal = await db.get_user_vc(interaction.user.id)
        if bal < cost:
            await interaction.response.send_message(
                f"❌ **Insufficient VC!** You need `💰 {cost:,} VC`, but currently have `💰 {bal:,} VC`.\n"
                f"Claim daily VC with `/nbadaily` or quick-sell duplicates with `/nbasell`.",
                ephemeral=True
            )
            return

        deducted = await db.deduct_user_vc(interaction.user.id, cost)
        if not deducted:
            await interaction.response.send_message("❌ Failed to process VC transaction.", ephemeral=True)
            return

        card = roll_pack_card(self.pack_id, interaction.user.id)
        existing_cards = await db.get_user_nba_cards(interaction.user.id)
        existing_cids = [c["card_id"].lower() for c in existing_cards]
        is_new = card["id"].lower() not in existing_cids
        copies_now = existing_cids.count(card["id"].lower()) + 1

        await db.add_user_nba_card(interaction.user.id, card["id"], source=f"pack_{self.pack_id}")
        new_bal = await db.get_user_vc(interaction.user.id)

        self.card = card
        self.new_bal = new_bal
        self.is_new = is_new
        self.copies = copies_now

        embed = build_openpack_embed(interaction.user, pack_data, card, new_bal, is_new=is_new, copies=copies_now)
        new_view = NBAPackOpenView(interaction.user, self.pack_id, card, new_bal, is_new, copies_now)
        try:
            card_buf = generate_nba_card_graphic(card, is_mystery=False)
            card_file = discord.File(fp=card_buf, filename="nba_card.png")
            await interaction.response.send_message(embed=embed, file=card_file, view=new_view)
        except Exception:
            await interaction.response.send_message(embed=embed, view=new_view)

    async def view_in_dex(self, interaction: discord.Interaction):
        cards = await db.get_user_nba_cards(interaction.user.id)
        vc = await db.get_user_vc(interaction.user.id)
        embed, _, _ = build_nbadex_embed(interaction.user, cards, "all", 1, 6, vc)
        view = NBADexView(interaction.user, interaction.user, cards, "all", 1, vc)
        await interaction.response.send_message(embed=embed, view=view, ephemeral=True)

    async def inspect_pulled_card(self, interaction: discord.Interaction):
        cards = await db.get_user_nba_cards(interaction.user.id)
        copies = sum(1 for c in cards if c["card_id"].lower() == self.card["id"].lower())
        is_fav = any(c.get("is_favorite") for c in cards if c["card_id"].lower() == self.card["id"].lower())
        embed = build_nbacard_embed(self.card, copies_owned=copies, is_fav=is_fav, owner_user=interaction.user)
        view = NBACardInspectView(self.card, interaction.user, copies, is_fav, author=interaction.user)
        await interaction.response.send_message(embed=embed, view=view, ephemeral=True)


class NBACardInspectView(discord.ui.View):
    def __init__(self, card: Dict[str, Any], owner_user: discord.User, copies: int, is_fav: bool, author: Optional[discord.User] = None, parent_dex_view: Optional[NBADexView] = None):
        super().__init__(timeout=120.0)
        self.card = card
        self.owner_user = owner_user
        self.copies = copies
        self.is_fav = is_fav
        self.author = author or owner_user
        self.parent_dex_view = parent_dex_view

        tier_info = NBA_2K_TIERS.get(card["tier"], NBA_2K_TIERS["gold"])
        
        fav_label = "Unfavorite" if is_fav else "Favorite"
        fav_style = discord.ButtonStyle.secondary if is_fav else discord.ButtonStyle.primary
        self.fav_btn = discord.ui.Button(label=fav_label, style=fav_style, emoji="⭐", row=0)
        self.fav_btn.callback = self.toggle_fav
        self.add_item(self.fav_btn)

        sell_label = f"Quick-Sell ({tier_info['quick_sell']:,} VC)"
        self.sell_btn = discord.ui.Button(label=sell_label, style=discord.ButtonStyle.danger, emoji="💰", disabled=(copies <= 0), row=0)
        self.sell_btn.callback = self.quick_sell
        self.add_item(self.sell_btn)

        if self.parent_dex_view:
            self.back_btn = discord.ui.Button(label="Back to Binder", style=discord.ButtonStyle.secondary, emoji="🎴", row=0)
            self.back_btn.callback = self.back_to_binder
            self.add_item(self.back_btn)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("❌ This is not your inspection session.", ephemeral=True)
            return False
        return True

    async def toggle_fav(self, interaction: discord.Interaction):
        # Toggle in DB
        cards = await db.get_user_nba_cards(interaction.user.id)
        card_entry = next((c for c in cards if c["card_id"].lower() == self.card["id"].lower()), None)
        if not card_entry:
            await interaction.response.send_message("❌ You do not own this card.", ephemeral=True)
            return

        new_fav = not self.is_fav
        await db.execute("UPDATE user_nba_cards SET is_favorite = ? WHERE user_id = ? AND card_id = ?", new_fav, str(interaction.user.id), self.card["id"])
        self.is_fav = new_fav
        self.fav_btn.label = "Unfavorite" if new_fav else "Favorite"
        self.fav_btn.style = discord.ButtonStyle.secondary if new_fav else discord.ButtonStyle.primary

        embed = build_nbacard_embed(self.card, copies_owned=self.copies, is_fav=self.is_fav, owner_user=self.owner_user)
        await interaction.response.edit_message(embed=embed, view=self)

    async def quick_sell(self, interaction: discord.Interaction):
        if self.copies <= 0:
            await interaction.response.send_message("❌ You have 0 copies of this card left to sell.", ephemeral=True)
            return

        tier_info = NBA_2K_TIERS.get(self.card["tier"], NBA_2K_TIERS["gold"])
        sell_val = tier_info["quick_sell"]

        removed = await db.remove_user_nba_card(interaction.user.id, self.card["id"])
        if not removed:
            await interaction.response.send_message("❌ Could not process quick-sell.", ephemeral=True)
            return

        new_bal = await db.add_user_vc(interaction.user.id, sell_val)
        self.copies -= 1
        if self.copies <= 0:
            self.sell_btn.disabled = True

        embed = build_nbacard_embed(self.card, copies_owned=self.copies, is_fav=self.is_fav, owner_user=self.owner_user)
        await interaction.response.edit_message(embed=embed, view=self)
        await interaction.followup.send(
            f"💰 **Card Sold!** Sold 1x **{self.card['name']}** for `💰 {sell_val:,} VC`!\n• **New Balance:** `💰 {new_bal:,} VC`",
            ephemeral=True
        )

    async def back_to_binder(self, interaction: discord.Interaction):
        if self.parent_dex_view:
            await self.parent_dex_view.refresh_message(interaction)


CREATOR_ID_INT = 719932313919684670

def is_event_creator(user: Union[discord.User, discord.Member, int, str]) -> bool:
    """Checks if the user is the bot creator (719932313919684670)."""
    try:
        uid = user.id if hasattr(user, "id") else int(str(user))
        return uid == CREATOR_ID_INT
    except Exception:
        return False


TIER_ALIASES_MAP: Dict[str, str] = {
    "gold": "gold", "emerald": "gold", "yellow": "gold",
    "ruby": "ruby", "sapphire": "ruby", "red": "ruby", "blue": "ruby",
    "amethyst": "amethyst", "purple": "amethyst", "amy": "amethyst",
    "diamond": "diamond", "pink_diamond": "diamond", "pink diamond": "diamond", "pd": "diamond",
    "galaxy_opal": "galaxy_opal", "galaxy opal": "galaxy_opal", "opal": "galaxy_opal", "go": "galaxy_opal",
    "dark_matter": "dark_matter", "dark matter": "dark_matter", "dm": "dark_matter", "goat": "dark_matter", "g.o.a.t.": "dark_matter",
    "exclusive": "exclusive", "excl": "exclusive", "immortal": "exclusive"
}


class NBASellBulkConfirmView(discord.ui.View):
    """Interactive confirmation dialog for NBA card bulk sales with atomic execution & itemized receipt."""
    def __init__(
        self,
        author: Union[discord.User, discord.Member],
        card_row_ids: List[int],
        breakdown: List[Dict[str, Any]],
        total_vc: int,
        total_cards: int,
        is_interaction: bool = True
    ):
        super().__init__(timeout=60.0)
        self.author = author
        self.card_row_ids = card_row_ids
        self.breakdown = breakdown
        self.total_vc = total_vc
        self.total_cards = total_cards
        self.is_interaction = is_interaction
        self.message: Optional[Union[discord.Message, discord.WebhookMessage]] = None

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("❌ This confirmation is only for the player selling these cards.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Confirm Sell", style=discord.ButtonStyle.success, emoji="✅", row=0)
    async def confirm_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        try:
            for child in self.children:
                child.disabled = True

            success, msg, new_bal = await db.bulk_remove_user_nba_cards(self.author.id, self.card_row_ids, self.total_vc)
            if not success:
                await interaction.response.edit_message(content=f"❌ **Bulk Sell Failed:** {msg}", embed=None, view=None)
                self.stop()
                return

            receipt_embed = discord.Embed(
                title="🧾 NBA Card Sale Receipt",
                description=(
                    f"✅ **Bulk Sale Completed!**\n"
                    f"Successfully sold **{self.total_cards:,}** card{'s' if self.total_cards != 1 else ''} for **💰 {self.total_vc:,} VC**!\n\n"
                    f"💰 **New VC Balance:** `💰 {new_bal:,} VC`"
                ),
                color=discord.Color.green()
            )
            receipt_embed.set_author(
                name=f"{self.author.display_name}'s Sale Receipt",
                icon_url=self.author.display_avatar.url if hasattr(self.author, 'display_avatar') else None
            )

            lines = []
            for item in self.breakdown[:12]:
                lines.append(f"• **{item['qty']}x** {item['emoji']} `[{item['ovr']} OVR]` **{item['name']}** — `💰 {item['subtotal']:,} VC` (`{item['unit_price']:,}` ea)")

            if len(self.breakdown) > 12:
                extra_cards = sum(item['qty'] for item in self.breakdown[12:])
                extra_types = len(self.breakdown) - 12
                extra_vc = sum(item['subtotal'] for item in self.breakdown[12:])
                lines.append(f"• *... and {extra_cards:,} more card{'s' if extra_cards != 1 else ''} across {extra_types} other card types (`💰 {extra_vc:,} VC`)*")

            receipt_embed.add_field(name="📋 Cards Sold", value="\n".join(lines) if lines else "No items", inline=False)
            receipt_embed.set_footer(text=f"Atomic DB Transaction ID: #{int(time.time())} • Sweety NBA Economy")
            receipt_embed.timestamp = discord.utils.utcnow()

            await interaction.response.edit_message(embed=receipt_embed, view=None)
            self.stop()
        except Exception as e:
            logger.error(f"Error in NBASellBulkConfirmView.confirm_btn: {e}", exc_info=True)
            if not interaction.response.is_done():
                await interaction.response.send_message(f"❌ Error during bulk sell: {e}", ephemeral=True)

    @discord.ui.button(label="Cancel", style=discord.ButtonStyle.secondary, emoji="❌", row=0)
    async def cancel_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        for child in self.children:
            child.disabled = True
        await interaction.response.edit_message(content="❌ **Bulk sell cancelled.** No cards were sold and your collection was not modified.", embed=None, view=None)
        self.stop()

    async def on_timeout(self):
        try:
            for child in self.children:
                child.disabled = True
            if self.message:
                await self.message.edit(view=self)
        except Exception:
            pass


async def handle_nbasell(
    user: Union[discord.User, discord.Member],
    send_response: Callable,
    card_query: Optional[str] = None,
    quantity: Optional[Union[str, int]] = None,
    tier_filter: Optional[str] = None,
    all_dupes: bool = False,
    is_interaction: bool = False
):
    """Processes NBA card sell requests across all bulk modes with strict card protections and atomic confirmation."""
    try:
        user_cards = await db.get_user_nba_cards(user.id)
        if not user_cards:
            await send_response("❌ You do not own any NBA cards in your binder yet! Rip packs using `/openpack` or claim daily cards.")
            return

        # Check if card_query is parsing shorthand for dupes or tier
        if card_query:
            cq_clean = str(card_query).strip()
            cq_lower = cq_clean.lower()
            if cq_lower in ["dupes all", "all dupes", "dupes", "all_dupes", "duplicates all", "all duplicates", "duplicates", "all"]:
                all_dupes = True
                card_query = None
            else:
                words = cq_lower.split()
                if len(words) == 2 and "all" in words:
                    cand = words[0] if words[1] == "all" else words[1]
                    if cand in TIER_ALIASES_MAP:
                        tier_filter = TIER_ALIASES_MAP[cand]
                        card_query = None
                elif len(words) >= 2 and words[-1] == "all" and " ".join(words[:-1]) in TIER_ALIASES_MAP:
                    tier_filter = TIER_ALIASES_MAP[" ".join(words[:-1])]
                    card_query = None
                elif len(words) >= 2 and words[0] == "all" and " ".join(words[1:]) in TIER_ALIASES_MAP:
                    tier_filter = TIER_ALIASES_MAP[" ".join(words[1:])]
                    card_query = None
                elif len(words) >= 2 and words[-1] in ["dupes", "dupe", "duplicates", "duplicate"]:
                    card_query = cq_clean.rsplit(" ", 1)[0].strip()
                    quantity = "dupes"
                elif len(words) >= 2 and words[-1].isdigit():
                    # check if full query matches a real card first
                    if not get_nba_card(cq_clean):
                        card_query = cq_clean.rsplit(" ", 1)[0].strip()
                        quantity = int(words[-1])

        # MODE 1: All duplicates across entire collection
        if all_dupes:
            grouped = {}
            for c in user_cards:
                grouped.setdefault(c["card_id"].lower(), []).append(c)

            selected_row_ids = []
            breakdown_dict = {}

            for cid, copies in grouped.items():
                if len(copies) <= 1:
                    continue
                sample_card = get_nba_card(copies[0]["card_id"])
                # Protection: Holo Foil cards cannot be sold in bulk
                if bool(sample_card and (sample_card.get("is_holo") or str(cid).startswith("holo_"))):
                    continue
                
                # Keep 1 copy!
                to_sell_copies = copies[1:]
                tier = (sample_card.get("tier") if sample_card else "gold") or "gold"
                tier_info = NBA_2K_TIERS.get(tier, NBA_2K_TIERS["gold"])
                unit_price = tier_info.get("quick_sell", 100)
                card_name = sample_card.get("name", cid.replace("-", " ").title()) if sample_card else cid
                ovr = sample_card.get("ovr", 80) if sample_card else 80
                emoji = tier_info.get("emoji", "🟡")

                for row in to_sell_copies:
                    selected_row_ids.append(row["id"])

                qty = len(to_sell_copies)
                subtotal = qty * unit_price
                breakdown_dict[cid] = {
                    "name": card_name,
                    "tier": tier,
                    "ovr": ovr,
                    "emoji": emoji,
                    "qty": qty,
                    "unit_price": unit_price,
                    "subtotal": subtotal
                }

            if not selected_row_ids:
                await send_response("❌ You do not have any duplicate cards eligible for bulk selling in your collection.\n*(Holo Foil cards and single 1x copies are protected)*")
                return

            breakdown = sorted(breakdown_dict.values(), key=lambda x: x["subtotal"], reverse=True)
            mode_desc = "all duplicate copies in your collection (keeping 1 copy of each)"

        # MODE 2: Specific Tier selling
        elif tier_filter:
            target_tier = TIER_ALIASES_MAP.get(str(tier_filter).lower().strip(), str(tier_filter).lower().strip())
            tier_info = NBA_2K_TIERS.get(target_tier, NBA_2K_TIERS.get("gold"))

            grouped = {}
            for c in user_cards:
                sample_card = get_nba_card(c["card_id"])
                if not sample_card:
                    continue
                c_tier = sample_card.get("tier", "").lower()
                if c_tier != target_tier:
                    continue
                # Protection: Holo Foil cards cannot be sold in bulk
                if sample_card.get("is_holo") or str(c["card_id"]).lower().startswith("holo_"):
                    continue
                grouped.setdefault(c["card_id"].lower(), []).append((c, sample_card))

            selected_row_ids = []
            breakdown_dict = {}

            for cid, items in grouped.items():
                sample_card = items[0][1]
                # Protection: Cannot sell last copy of Exclusive card
                if target_tier == "exclusive" or sample_card.get("is_exclusive") or str(cid).startswith("excl-"):
                    if len(items) <= 1:
                        continue
                    to_sell_items = items[1:]
                else:
                    to_sell_items = items

                unit_price = tier_info.get("quick_sell", 100)
                card_name = sample_card.get("name", cid)
                ovr = sample_card.get("ovr", 80)
                emoji = tier_info.get("emoji", "🟡")

                for row, _ in to_sell_items:
                    selected_row_ids.append(row["id"])

                qty = len(to_sell_items)
                subtotal = qty * unit_price
                breakdown_dict[cid] = {
                    "name": card_name,
                    "tier": target_tier,
                    "ovr": ovr,
                    "emoji": emoji,
                    "qty": qty,
                    "unit_price": unit_price,
                    "subtotal": subtotal
                }

            if not selected_row_ids:
                await send_response(f"❌ You have no eligible **{tier_info['name']}** cards to sell.\n*(Holo Foil cards and single 1x Exclusive cards are protected)*")
                return

            breakdown = sorted(breakdown_dict.values(), key=lambda x: x["subtotal"], reverse=True)
            mode_desc = f"all eligible {tier_info['emoji']} **{tier_info['name']}** cards"

        # MODE 3: Specific Card (with quantity or dupes)
        elif card_query:
            card_obj = get_nba_card(card_query)
            if not card_obj:
                await send_response(f"❌ Card `{card_query}` not found in catalog.")
                return

            cid = card_obj["id"].lower()
            matching = [c for c in user_cards if c["card_id"].lower() == cid]
            owned_count = len(matching)

            if owned_count == 0:
                await send_response(f"❌ You do not own any copies of **{card_obj['name']}** (`{card_obj['id']}`).")
                return

            is_holo = bool(card_obj.get("is_holo") or str(card_obj["id"]).lower().startswith("holo_"))
            is_exclusive = bool(card_obj.get("tier") == "exclusive" or str(card_obj["id"]).lower().startswith("excl-") or card_obj.get("is_exclusive"))

            # Check quantity
            qty_str = str(quantity).strip().lower() if quantity is not None else ""
            if qty_str in ["dupes", "dupe", "duplicates", "duplicate"]:
                if is_holo:
                    await send_response(f"❌ **{card_obj['name']}** is a Holo Foil card! Holo Foil cards are protected from bulk selling.")
                    return
                if owned_count <= 1:
                    await send_response(f"❌ You do not have duplicate copies of **{card_obj['name']}** to sell (you own {owned_count} copy).")
                    return
                to_sell_copies = matching[1:]
            elif qty_str == "all":
                if is_exclusive:
                    if owned_count <= 1:
                        await send_response(f"❌ You cannot sell your last copy of Exclusive card **{card_obj['name']}**! Exclusive cards are protected.")
                        return
                    to_sell_copies = matching[1:]
                elif is_holo and owned_count > 1:
                    await send_response("❌ Holo Foil cards are protected from bulk selling.")
                    return
                else:
                    to_sell_copies = matching
            elif qty_str.isdigit() or isinstance(quantity, int):
                req_qty = int(quantity)
                if req_qty <= 0:
                    await send_response("❌ Sell quantity must be at least 1.")
                    return
                if req_qty > owned_count:
                    await send_response(f"❌ You only own **{owned_count}** cop{'ies' if owned_count != 1 else 'y'} of **{card_obj['name']}**, but requested to sell **{req_qty}**.")
                    return
                if is_holo and req_qty > 1:
                    await send_response(f"❌ **{card_obj['name']}** is a Holo Foil card! Holo Foil cards are protected from bulk selling.")
                    return
                if is_exclusive and req_qty >= owned_count:
                    await send_response(f"❌ You cannot sell all copies of Exclusive card **{card_obj['name']}**! You must keep at least 1 copy in your collection.")
                    return
                to_sell_copies = matching[:req_qty]
            else:
                # Default single card sell
                if is_exclusive and owned_count == 1:
                    await send_response(f"❌ You cannot sell your last copy of Exclusive card **{card_obj['name']}**! Exclusive cards are protected.")
                    return
                to_sell_copies = matching[:1]

            tier = card_obj.get("tier", "gold")
            tier_info = NBA_2K_TIERS.get(tier, NBA_2K_TIERS["gold"])
            unit_price = tier_info.get("quick_sell", 100)
            if is_holo:
                unit_price = int(unit_price * 1.5)

            selected_row_ids = [c["id"] for c in to_sell_copies]
            qty = len(to_sell_copies)
            subtotal = qty * unit_price
            breakdown = [{
                "name": card_obj["name"],
                "tier": tier,
                "ovr": card_obj.get("ovr", 80),
                "emoji": tier_info.get("emoji", "🟡"),
                "qty": qty,
                "unit_price": unit_price,
                "subtotal": subtotal
            }]
            mode_desc = f"{qty}x {tier_info['emoji']} **[{card_obj.get('ovr', 80)} OVR] {card_obj['name']}**"

        else:
            # No arguments given -> display helpful usage guide
            help_embed = discord.Embed(
                title="💰 NBA Card Sell & Bulk Sell System",
                description=(
                    "Sell unwanted cards or duplicates for instant **VC (Virtual Currency)**.\n\n"
                    "**Command Examples:**\n"
                    "• `/nbasell card: Curry quantity: 5` — Sell 5 copies of Stephen Curry\n"
                    "• `/nbasell card: Curry quantity: dupes` — Sell all duplicates of Curry, keeping 1\n"
                    "• `/nbasell tier: gold` — Bulk sell all Gold tier cards you own\n"
                    "• `/nbasell all_dupes: True` — Bulk sell all duplicate cards across your entire binder\n\n"
                    "**Prefix Command Examples:**\n"
                    "• `!nbasell Curry 5` — Sell 5 copies\n"
                    "• `!nbasell Curry dupes` — Sell all duplicates of Curry\n"
                    "• `!nbasell gold all` — Sell all Gold tier cards\n"
                    "• `!nbasell dupes all` — Sell all duplicate cards across entire collection\n\n"
                    "🛡️ **Protections:**\n"
                    "• Last copy of Exclusive cards cannot be sold.\n"
                    "• Holo Foil cards are protected from bulk selling.\n"
                    "• Interactive button confirmation required before execution."
                ),
                color=discord.Color.gold()
            )
            await send_response(embed=help_embed)
            return

        total_cards = len(selected_row_ids)
        total_vc = sum(item["subtotal"] for item in breakdown)

        confirm_embed = discord.Embed(
            title="⚠️ Confirm Bulk Card Sale",
            description=(
                f"Are you sure you want to sell **{total_cards:,}** card{'s' if total_cards != 1 else ''} for a total of **💰 {total_vc:,} VC**?\n\n"
                f"• **Target:** {mode_desc}\n"
                f"• **Total Cards:** `{total_cards:,}`\n"
                f"• **Total VC Payout:** `💰 {total_vc:,} VC`\n\n"
                f"*Click **Confirm Sell** to execute atomically or **Cancel** to abort.*"
            ),
            color=discord.Color.orange()
        )
        confirm_embed.set_author(name=f"{user.display_name} — Sell Confirmation", icon_url=user.display_avatar.url if hasattr(user, 'display_avatar') else None)

        lines = []
        for item in breakdown[:10]:
            lines.append(f"• **{item['qty']}x** {item['emoji']} `[{item['ovr']} OVR]` **{item['name']}** — `💰 {item['subtotal']:,} VC` (`{item['unit_price']:,}` ea)")
        if len(breakdown) > 10:
            extra_c = sum(item['qty'] for item in breakdown[10:])
            extra_t = len(breakdown) - 10
            extra_v = sum(item['subtotal'] for item in breakdown[10:])
            lines.append(f"• *... and {extra_c:,} more card{'s' if extra_c != 1 else ''} across {extra_t} other card types (`💰 {extra_v:,} VC`)*")

        confirm_embed.add_field(name="📋 Itemized Summary", value="\n".join(lines) if lines else "None", inline=False)
        confirm_embed.set_footer(text="Confirmation expires in 60 seconds • Holo Foil & 1x Exclusive protected")

        view = NBASellBulkConfirmView(
            author=user,
            card_row_ids=selected_row_ids,
            breakdown=breakdown,
            total_vc=total_vc,
            total_cards=total_cards,
            is_interaction=is_interaction
        )

        sent_msg = await send_response(embed=confirm_embed, view=view)
        view.message = sent_msg

    except Exception as e:
        logger.error(f"Error in handle_nbasell: {e}", exc_info=True)
        await send_response(f"❌ Error processing sell request: {e}")


