class NBACardTradeView(discord.ui.View):
    def __init__(
        self,
        sender_user: discord.User,
        target_user: discord.User,
        cards_a: Optional[List[Dict[str, Any]]] = None,
        cards_b: Optional[List[Dict[str, Any]]] = None,
        vc_a: int = 0,
        vc_b: int = 0
    ):
        super().__init__(timeout=300.0)
        self.sender_user = sender_user
        self.target_user = target_user
        self.cards_a: List[Dict[str, Any]] = list(cards_a) if cards_a else []
        self.cards_b: List[Dict[str, Any]] = list(cards_b) if cards_b else []
        self.vc_a: int = max(0, int(vc_a or 0))
        self.vc_b: int = max(0, int(vc_b or 0))
        self.sender_ready: bool = False
        self.target_ready: bool = False
        self.status: str = "pending"
        self.is_cancelled: bool = False
        self.is_finalized: bool = False
        self.countdown_task: Optional[asyncio.Task] = None
        self.message: Optional[discord.Message] = None
        self._lock = asyncio.Lock()
        self.update_button_labels()

    def update_button_labels(self):
        a_name = self.sender_user.display_name[:10]
        b_name = self.target_user.display_name[:10]
        
        self.ready_a_btn.label = f"Ready ({a_name}) ✅" if self.sender_ready else f"Ready ({a_name}) ⏳"
        self.ready_a_btn.style = discord.ButtonStyle.success if self.sender_ready else discord.ButtonStyle.secondary
        
        self.ready_b_btn.label = f"Ready ({b_name}) ✅" if self.target_ready else f"Ready ({b_name}) ⏳"
        self.ready_b_btn.style = discord.ButtonStyle.success if self.target_ready else discord.ButtonStyle.secondary

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id not in (self.sender_user.id, self.target_user.id):
            await interaction.response.send_message(
                f"❌ Only {self.sender_user.mention} and {self.target_user.mention} can interact with this trade floor.",
                ephemeral=True
            )
            return False
        return True

    @discord.ui.button(label="➕ Offer Card", style=discord.ButtonStyle.primary, row=0)
    async def add_card_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.status == "countdown":
            return await interaction.response.send_message("🔒 Trade is locked in countdown! Click Cancel to abort.", ephemeral=True)
        if self.is_finalized or self.is_cancelled:
            return await interaction.response.send_message("❌ This trade session is closed.", ephemeral=True)

        is_sender = interaction.user.id == self.sender_user.id
        current_cards = self.cards_a if is_sender else self.cards_b
        if len(current_cards) >= 5:
            return await interaction.response.send_message("❌ Maximum limit of 5 cards reached on your side of the table.", ephemeral=True)

        modal = NBATradeAddCardModal(self, is_sender)
        await interaction.response.send_modal(modal)

    @discord.ui.button(label="➖ Remove Card", style=discord.ButtonStyle.secondary, row=0)
    async def remove_card_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.status == "countdown":
            return await interaction.response.send_message("🔒 Trade is locked in countdown! Click Cancel to abort.", ephemeral=True)
        if self.is_finalized or self.is_cancelled:
            return await interaction.response.send_message("❌ This trade session is closed.", ephemeral=True)

        is_sender = interaction.user.id == self.sender_user.id
        current_cards = self.cards_a if is_sender else self.cards_b
        if not current_cards:
            return await interaction.response.send_message("❌ You have not placed any cards on the table yet.", ephemeral=True)

        modal = NBATradeRemoveCardModal(self, is_sender)
        await interaction.response.send_modal(modal)

    @discord.ui.button(label="💰 Offer VC", style=discord.ButtonStyle.success, emoji="💰", row=0)
    async def offer_vc_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.status == "countdown":
            return await interaction.response.send_message("🔒 Trade is locked in countdown! Click Cancel to abort.", ephemeral=True)
        if self.is_finalized or self.is_cancelled:
            return await interaction.response.send_message("❌ This trade session is closed.", ephemeral=True)

        is_sender = interaction.user.id == self.sender_user.id
        modal = NBATradeVCModal(self, is_sender)
        await interaction.response.send_modal(modal)

    @discord.ui.button(label="Ready (Sender) ⏳", style=discord.ButtonStyle.secondary, row=1)
    async def ready_a_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.sender_user.id:
            return await interaction.response.send_message(f"❌ Only {self.sender_user.mention} can click this button.", ephemeral=True)
        await self.toggle_ready(interaction, is_sender=True)

    @discord.ui.button(label="Ready (Target) ⏳", style=discord.ButtonStyle.secondary, row=1)
    async def ready_b_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.target_user.id:
            return await interaction.response.send_message(f"❌ Only {self.target_user.mention} can click this button.", ephemeral=True)
        await self.toggle_ready(interaction, is_sender=False)

    @discord.ui.button(label="Cancel / Decline", style=discord.ButtonStyle.danger, emoji="❌", row=1)
    async def cancel_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        async with self._lock:
            self.is_cancelled = True
            self.status = "declined"
            if self.countdown_task and not self.countdown_task.done():
                self.countdown_task.cancel()

            for item in self.children:
                item.disabled = True

            embed = build_multi_trade_embed(
                self.sender_user, self.target_user,
                self.cards_a, self.cards_b,
                False, False,
                status="declined",
                vc_a=self.vc_a, vc_b=self.vc_b
            )
            await interaction.response.edit_message(embed=embed, view=self)
            await interaction.followup.send(f"🛑 Trade was cancelled by {interaction.user.mention}.")

    async def handle_vc_modal(self, interaction: discord.Interaction, raw_val: str, is_sender: bool):
        async with self._lock:
            cleaned = raw_val.replace(",", "").replace("$", "").replace(" ", "").lower()
            if cleaned.endswith("k"):
                try:
                    amount = int(float(cleaned[:-1]) * 1000)
                except ValueError:
                    amount = -1
            elif cleaned.endswith("m"):
                try:
                    amount = int(float(cleaned[:-1]) * 1000000)
                except ValueError:
                    amount = -1
            else:
                try:
                    amount = int(cleaned)
                except ValueError:
                    amount = -1

            if amount < 0:
                return await interaction.response.send_message("❌ Please enter a valid non-negative number for VC.", ephemeral=True)

            user_id = self.sender_user.id if is_sender else self.target_user.id
            current_vc = await db.get_user_vc(user_id)
            if amount > current_vc:
                return await interaction.response.send_message(
                    f"❌ Insufficient VC! You have **`{current_vc:,}` VC**, but tried to offer **`{amount:,}` VC**.",
                    ephemeral=True
                )

            if is_sender:
                self.vc_a = amount
            else:
                self.vc_b = amount

            # Reset readiness on offer change
            self.sender_ready = False
            self.target_ready = False
            self.status = "pending"
            if self.countdown_task and not self.countdown_task.done():
                self.countdown_task.cancel()

            self.update_button_labels()
            embed = build_multi_trade_embed(
                self.sender_user, self.target_user,
                self.cards_a, self.cards_b,
                self.sender_ready, self.target_ready,
                status="pending",
                vc_a=self.vc_a, vc_b=self.vc_b
            )
            await interaction.response.edit_message(embed=embed, view=self)

    async def handle_add_card_modal(self, interaction: discord.Interaction, query: str, is_sender: bool):
        async with self._lock:
            card_obj = get_nba_card(query)
            if not card_obj:
                return await interaction.response.send_message(f"❌ Card `{query}` not found in 2K Mobile catalog.", ephemeral=True)

            if card_obj.get("tier") == "exclusive" or str(card_obj.get("id", "")).startswith("excl-") or card_obj.get("is_exclusive"):
                return await interaction.response.send_message("❌ **Exclusive cards cannot be traded!** They are non-transferable account-bound trophies.", ephemeral=True)

            user_id = self.sender_user.id if is_sender else self.target_user.id
            owned_records = await db.get_user_nba_cards(user_id)
            cid = card_obj["id"].lower()
            owned_count = sum(1 for r in owned_records if str(r.get("card_id", "")).lower() == cid)

            current_cards = self.cards_a if is_sender else self.cards_b
            already_offered = sum(1 for c in current_cards if c["id"].lower() == cid)

            if owned_count <= already_offered:
                return await interaction.response.send_message(
                    f"❌ You own `{owned_count}` copies of **{card_obj['name']}** and already have `{already_offered}` on the table.",
                    ephemeral=True
                )

            current_cards.append(card_obj)
            # Reset readiness on offer change
            self.sender_ready = False
            self.target_ready = False
            self.status = "pending"
            if self.countdown_task and not self.countdown_task.done():
                self.countdown_task.cancel()

            self.update_button_labels()
            embed = build_multi_trade_embed(
                self.sender_user, self.target_user,
                self.cards_a, self.cards_b,
                self.sender_ready, self.target_ready,
                status="pending",
                vc_a=self.vc_a, vc_b=self.vc_b
            )
            await interaction.response.edit_message(embed=embed, view=self)

    async def handle_remove_card_modal(self, interaction: discord.Interaction, query: str, is_sender: bool):
        async with self._lock:
            current_cards = self.cards_a if is_sender else self.cards_b
            if not current_cards:
                return await interaction.response.send_message("❌ No cards to remove.", ephemeral=True)

            removed = None
            if query.isdigit():
                idx = int(query) - 1
                if 0 <= idx < len(current_cards):
                    removed = current_cards.pop(idx)
            else:
                q_clean = query.strip().lower()
                for i, c in enumerate(current_cards):
                    if c["name"].lower() == q_clean or c["id"].lower() == q_clean:
                        removed = current_cards.pop(i)
                        break

            if not removed:
                return await interaction.response.send_message(f"❌ Could not find card `{query}` in your active offer.", ephemeral=True)

            # Reset readiness on change
            self.sender_ready = False
            self.target_ready = False
            self.status = "pending"
            if self.countdown_task and not self.countdown_task.done():
                self.countdown_task.cancel()

            self.update_button_labels()
            embed = build_multi_trade_embed(
                self.sender_user, self.target_user,
                self.cards_a, self.cards_b,
                self.sender_ready, self.target_ready,
                status="pending",
                vc_a=self.vc_a, vc_b=self.vc_b
            )
            await interaction.response.edit_message(embed=embed, view=self)

    async def toggle_ready(self, interaction: discord.Interaction, is_sender: bool):
        async with self._lock:
            if not self.cards_a and not self.cards_b and self.vc_a <= 0 and self.vc_b <= 0:
                return await interaction.response.send_message("❌ At least one card or VC amount must be placed on the trade floor.", ephemeral=True)

            # Pre-validate VC balances before toggling to ready
            if is_sender and not self.sender_ready and self.vc_a > 0:
                bal_a = await db.get_user_vc(self.sender_user.id)
                if bal_a < self.vc_a:
                    return await interaction.response.send_message(f"❌ You have insufficient VC ({bal_a:,} < {self.vc_a:,} VC). Please update your VC offer.", ephemeral=True)
            elif not is_sender and not self.target_ready and self.vc_b > 0:
                bal_b = await db.get_user_vc(self.target_user.id)
                if bal_b < self.vc_b:
                    return await interaction.response.send_message(f"❌ You have insufficient VC ({bal_b:,} < {self.vc_b:,} VC). Please update your VC offer.", ephemeral=True)

            if is_sender:
                self.sender_ready = not self.sender_ready
            else:
                self.target_ready = not self.target_ready

            self.update_button_labels()

            # If both are ready, start 7-second countdown!
            if self.sender_ready and self.target_ready:
                self.status = "countdown"
                self.add_card_btn.disabled = True
                self.remove_card_btn.disabled = True
                self.offer_vc_btn.disabled = True
                self.ready_a_btn.disabled = True
                self.ready_b_btn.disabled = True

                embed = build_multi_trade_embed(
                    self.sender_user, self.target_user,
                    self.cards_a, self.cards_b,
                    self.sender_ready, self.target_ready,
                    status="countdown",
                    countdown_secs=7,
                    vc_a=self.vc_a, vc_b=self.vc_b
                )
                await interaction.response.edit_message(embed=embed, view=self)
                self.message = interaction.message
                self.countdown_task = asyncio.create_task(self.run_countdown_timer(interaction.message))
            else:
                self.status = "pending"
                embed = build_multi_trade_embed(
                    self.sender_user, self.target_user,
                    self.cards_a, self.cards_b,
                    self.sender_ready, self.target_ready,
                    status="pending",
                    vc_a=self.vc_a, vc_b=self.vc_b
                )
                await interaction.response.edit_message(embed=embed, view=self)

    async def run_countdown_timer(self, message: discord.Message):
        try:
            for sec in range(7, 0, -1):
                if self.is_cancelled or not (self.sender_ready and self.target_ready):
                    return

                embed = build_multi_trade_embed(
                    self.sender_user, self.target_user,
                    self.cards_a, self.cards_b,
                    self.sender_ready, self.target_ready,
                    status="countdown",
                    countdown_secs=sec,
                    vc_a=self.vc_a, vc_b=self.vc_b
                )
                try:
                    await message.edit(embed=embed, view=self)
                except Exception:
                    pass
                await asyncio.sleep(1)

            if self.is_cancelled or not (self.sender_ready and self.target_ready):
                return

            # Execute trade in database atomically
            card_a_ids = [c["id"] for c in self.cards_a]
            card_b_ids = [c["id"] for c in self.cards_b]

            success, err_msg = await db.execute_multi_card_trade(
                self.sender_user.id, self.target_user.id, card_a_ids, card_b_ids, self.vc_a, self.vc_b
            )

            self.is_finalized = True
            for item in self.children:
                item.disabled = True

            if success:
                self.status = "accepted"
                embed = build_multi_trade_embed(
                    self.sender_user, self.target_user,
                    self.cards_a, self.cards_b,
                    True, True,
                    status="accepted",
                    vc_a=self.vc_a, vc_b=self.vc_b
                )
                await message.edit(embed=embed, view=self)
                try:
                    summary_a_items = [f"**[{c['ovr']}] {c['name']}**" for c in self.cards_a]
                    if self.vc_a > 0:
                        summary_a_items.append(f"💰 **`{self.vc_a:,} VC`**")
                    summary_a = " + ".join(summary_a_items) if summary_a_items else "*None*"

                    summary_b_items = [f"**[{c['ovr']}] {c['name']}**" for c in self.cards_b]
                    if self.vc_b > 0:
                        summary_b_items.append(f"💰 **`{self.vc_b:,} VC`**")
                    summary_b = " + ".join(summary_b_items) if summary_b_items else "*None*"

                    await message.channel.send(
                        f"🎉 **Trade Executed!**\n"
                        f"• {self.sender_user.mention} received: {summary_b}\n"
                        f"• {self.target_user.mention} received: {summary_a}"
                    )
                except Exception:
                    pass
            else:
                self.status = "declined"
                embed = discord.Embed(
                    title="❌ Trade Execution Aborted",
                    description=f"Could not complete trade: {err_msg}",
                    color=discord.Color.red()
                )
                await message.edit(embed=embed, view=self)
        except asyncio.CancelledError:
            pass
        except Exception as e:
            logger.error(f"Error in trade countdown: {e}", exc_info=True)
        except asyncio.CancelledError:
            pass
        except Exception as e:
            logger.error(f"Error in trade countdown: {e}", exc_info=True)


class NBACatchModal(discord.ui.Modal, title="🏀 Catch the NBA 2K Player"):
    name_input = discord.ui.TextInput(
        label="Player Full Name or Nickname",
        placeholder="e.g. Stephen Curry, Wemby, MJ, LeBron...",
        required=True,
        min_length=2,
        max_length=50
    )

    def __init__(self, drop_data: Dict[str, Any], drop_msg: Optional[discord.Message] = None):
        super().__init__()
        self.drop_data = drop_data
        self.drop_msg = drop_msg

    async def on_submit(self, interaction: discord.Interaction):
        guess = self.name_input.value.strip()
        await handle_catch_attempt(interaction, guess, self.drop_data, self.drop_msg)


class NBAChatDropView(discord.ui.View):
    def __init__(self, card: Dict[str, Any], drop_id: str, channel_id: int):
        super().__init__(timeout=300.0)
        self.card = card
        self.drop_id = drop_id
        self.channel_id = channel_id

        self.enter_name_btn = discord.ui.Button(
            label="🏀 Enter Player Name",
            style=discord.ButtonStyle.success,
            emoji="🏀",
            row=0
        )
        self.enter_name_btn.callback = self.open_modal
        self.add_item(self.enter_name_btn)

        self.hint_btn = discord.ui.Button(
            label="💡 Get Hint",
            style=discord.ButtonStyle.secondary,
            emoji="💡",
            row=0
        )
        self.hint_btn.callback = self.give_hint
        self.add_item(self.hint_btn)

    async def open_modal(self, interaction: discord.Interaction):
        drop = get_active_nba_drop(interaction.channel_id, interaction.guild_id if interaction.guild else None)
        if not drop:
            await interaction.response.send_message("❌ There is no active wild card drop right now.", ephemeral=True)
            return
        if drop.get("spawner_id") and interaction.user.id == drop.get("spawner_id"):
            await interaction.response.send_message("❌ **Host Disqualified**: You spawned/hosted this card drop! As the event host, you cannot claim it—leave it for other server members to catch!", ephemeral=True)
            return
        if drop.get("claimed"):
            claimed_by = drop.get("claimed_by_name", "another player")
            await interaction.response.send_message(f"❌ **Too slow!** This player was already caught by **{claimed_by}**!", ephemeral=True)
            return
        modal = NBACatchModal(drop, interaction.message)
        await interaction.response.send_modal(modal)

    async def give_hint(self, interaction: discord.Interaction):
        drop = get_active_nba_drop(interaction.channel_id, interaction.guild_id if interaction.guild else None)
        if not drop or drop.get("claimed"):
            await interaction.response.send_message("❌ This drop has already ended.", ephemeral=True)
            return
        drop["hints_used"] = min(3, drop.get("hints_used", 1) + 1)
        hint_str = generate_player_hint(drop["card"]["name"], drop["hints_used"])
        await interaction.response.send_message(f"💡 **Player Name Hint:** `{hint_str}`", ephemeral=True)


async def handle_catch_attempt(
    interaction_or_ctx: Any,
    guess: str,
    drop: Optional[Dict[str, Any]] = None,
    drop_msg: Optional[discord.Message] = None
):
    """Unified handler for catch attempts across slash commands, prefix commands, modals, and direct chat typing."""
    try:
        is_interaction = isinstance(interaction_or_ctx, discord.Interaction)
        user = interaction_or_ctx.user if is_interaction else interaction_or_ctx.author
        channel_id = interaction_or_ctx.channel_id if is_interaction else interaction_or_ctx.channel.id
        guild_id = interaction_or_ctx.guild_id if is_interaction else (interaction_or_ctx.guild.id if interaction_or_ctx.guild else None)

        if not drop:
            drop = get_active_nba_drop(channel_id, guild_id)

        async def _send_ephemeral(text: str):
            if is_interaction:
                if not interaction_or_ctx.response.is_done():
                    await interaction_or_ctx.response.send_message(text, ephemeral=True)
                else:
                    await interaction_or_ctx.followup.send(text, ephemeral=True)
            elif isinstance(interaction_or_ctx, discord.Message):
                await interaction_or_ctx.reply(text, mention_author=True)
            elif hasattr(interaction_or_ctx, "send"):
                await interaction_or_ctx.send(text)

        if not drop:
            await _send_ephemeral("❌ There is no active wild NBA card drop in this channel right now. Keep chatting to spawn one!")
            return

        # Check if spawner is attempting to claim their own manual drop
        if drop.get("spawner_id") and user.id == drop.get("spawner_id"):
            await _send_ephemeral("❌ **Host Disqualified**: You spawned/hosted this card drop! As the event host, you cannot claim it—leave it for other server members to catch!")
            return

        # Check if already claimed
        if drop.get("claimed"):
            claimed_by = drop.get("claimed_by_name", "another player")
            await _send_ephemeral(f"❌ **Too slow!** This player was already caught by **{claimed_by}**! Wait for the next court drop.")
            return

        card = drop["card"]
        actual_name = card["name"]

        # Check if guess is correct
        if not is_correct_player_name(guess, actual_name):
            await _send_ephemeral(f"❌ **'{guess}' is incorrect!** Look closely at the team (**{card['team']}**), position (**{card['pos']}**), or use `!nbahint`!")
            return

        # Defer interaction if valid guess to allow Pillow generation
        if is_interaction and not interaction_or_ctx.response.is_done():
            await interaction_or_ctx.response.defer(ephemeral=False)

        # Correct guess! First user gets the card
        drop["claimed"] = True
        drop["claimed_by_id"] = user.id
        drop["claimed_by_name"] = user.display_name

        await db.add_user_nba_card(user.id, card["id"], source="chat_catch")
        new_bal = await db.add_user_vc(user.id, 150)
        user_cards = await db.get_user_nba_cards(user.id)
        copies = sum(1 for c in user_cards if c["card_id"].lower() == card["id"].lower())

        # Generate revealed card image
        card_buf = generate_nba_card_graphic(card, is_mystery=False)
        card_file = discord.File(fp=card_buf, filename="nba_card.png")
        success_embed = build_catch_success_embed(user, card, new_bal, copies)

        if is_interaction:
            await interaction_or_ctx.followup.send(embed=success_embed, file=card_file)
        elif isinstance(interaction_or_ctx, discord.Message):
            await interaction_or_ctx.reply(embed=success_embed, file=card_file, mention_author=True)
        elif hasattr(interaction_or_ctx, "send"):
            await interaction_or_ctx.send(embed=success_embed, file=card_file)

        # Update original drop message view & status
        target_drop_msg = drop_msg or drop.get("message")
        if target_drop_msg:
            try:
                disabled_view = discord.ui.View(timeout=1.0)
                btn = discord.ui.Button(label=f"✅ Caught by {user.display_name}!", style=discord.ButtonStyle.secondary, disabled=True, emoji="🏀")
                disabled_view.add_item(btn)
                await target_drop_msg.edit(view=disabled_view)
            except Exception as d_err:
                logger.debug(f"Could not edit drop message: {d_err}")

    except Exception as e:
        logger.error(f"Error in handle_catch_attempt: {e}", exc_info=True)
        try:
            chan = getattr(interaction_or_ctx, "channel", None)
            if chan and hasattr(chan, "send"):
                await chan.send(f"⚠️ Error claiming NBA card: `{e}`")
        except Exception:
            pass




