@bot.command(name="nbagive", aliases=["nbasend", "giftcard", "cardgive", "givecard"])
@commands.guild_only()
@commands.cooldown(1, 3.0, commands.BucketType.user)
async def nbagive_prefix_cmd(ctx: commands.Context, target: discord.Member, *, card: str):
    """Directly gift an NBA card to another member: !nbagive @user <card_name_or_id>"""
    try:
        if target.id == ctx.author.id:
            return await ctx.send("❌ You cannot gift cards to yourself!")
        if target.bot:
            return await ctx.send("❌ You cannot gift cards to a bot!")

        card_obj = get_nba_card(card)
        if not card_obj:
            return await ctx.send(f"❌ Card `{card}` was not found in the 2K Mobile catalog.")

        if card_obj.get("tier") == "exclusive" or str(card_obj.get("id", "")).startswith("excl-") or card_obj.get("is_exclusive"):
            return await ctx.send("❌ **Exclusive cards cannot be traded or gifted!** They are non-transferable account-bound trophies.")

        success, err_msg, row = await db.gift_user_nba_card(ctx.author.id, target.id, card_obj["id"])
        if not success:
            return await ctx.send(f"❌ {err_msg}")

        tier_info = NBA_2K_TIERS.get(card_obj["tier"], NBA_2K_TIERS["gold"])
        embed = discord.Embed(
            title=f"🎁 NBA 2K Mobile Card Gift Delivered!",
            description=(
                f"🎉 {ctx.author.mention} has gifted a card to {target.mention}!\n\n"
                f"• **Card:** {tier_info['emoji']} **[{card_obj['ovr']} OVR] {card_obj['name']}**\n"
                f"• **Position:** `{card_obj.get('pos', 'SF')}` | **Team:** `{card_obj.get('team', 'NBA')}`\n"
                f"• **Tier:** {tier_info['emoji']} **{tier_info['name']}**\n"
                f"• **Theme:** *{card_obj.get('theme', 'Signature Series')}*\n"
                f"• **Card ID:** `{card_obj['id']}`\n\n"
                f"*The card has been safely transferred to {target.display_name}'s collection binder!*"
            ),
            color=tier_info["color"]
        )
        is_holo = bool(card_obj.get("is_holo") or str(card_obj.get("id", "")).startswith("holo_"))
        cid = str(card_obj.get("id", "")).lower().replace("holo_", "").replace("holo-", "").strip()
        pname = card_obj.get("name", "").replace("🌟", "").replace("(Holo Foil)", "").replace("(Holo)", "").replace("(Foil)", "").strip()
        norm_p = unicodedata.normalize('NFKD', pname).encode('ascii', 'ignore').decode('utf-8').lower().replace(".", "").replace("'", "").strip()
        verified_thumb = (
            (NBA_HOLO_EDITION_MOMENT_URLS.get(cid) if is_holo else None)
            or NBA_CARD_SPECIFIC_MOMENT_URLS.get(cid)
            or NBA_PLAYER_MOMENT_ACTION_URLS.get(pname.lower().strip())
            or NBA_PLAYER_MOMENT_ACTION_URLS.get(norm_p)
        )
        if verified_thumb:
            embed.set_thumbnail(url=verified_thumb.split("?")[0])
        embed.set_footer(text=f"Gifted by {ctx.author.display_name} • Check binder with !nbadex")
        embed.timestamp = discord.utils.utcnow()

        await ctx.send(content=f"🔔 {target.mention}, you received a special 2K Mobile card gift from {ctx.author.mention}!", embed=embed)
    except Exception as e:
        logger.error(f"Error in !nbagive: {e}", exc_info=True)
        await ctx.send(f"❌ Error gifting card: {e}")


@bot.command(name="nbatrade", aliases=["tradecard", "trade"])
@commands.guild_only()
@commands.cooldown(1, 5.0, commands.BucketType.user)
async def nbatrade_prefix_cmd(ctx: commands.Context, target: discord.Member, your_card: Optional[str] = None, their_card: Optional[str] = None):
    """Open an interactive multi-card & VC trade panel: !nbatrade @user [your_card] [their_card]"""
    try:
        if target.id == ctx.author.id or target.bot:
            await ctx.send("❌ You cannot trade cards with yourself or bots.")
            return

        cards_a = []
        cards_b = []
        init_vc_a = 0

        if your_card:
            clean_str = your_card.lower().replace("vc", "").replace("$", "").replace(",", "").strip()
            if clean_str.isdigit():
                init_vc_a = int(clean_str)
                user_vc = await db.get_user_vc(ctx.author.id)
                if user_vc < init_vc_a:
                    return await ctx.send(f"❌ You only have **`{user_vc:,}` VC**, cannot offer **`{init_vc_a:,}` VC**.")
            else:
                c_a = get_nba_card(your_card)
                if not c_a:
                    return await ctx.send(f"❌ Your offered card `{your_card}` was not found.")
                if c_a.get("tier") == "exclusive" or str(c_a.get("id", "")).startswith("excl-") or c_a.get("is_exclusive"):
                    return await ctx.send("❌ **Exclusive cards cannot be traded!** They are non-transferable account-bound trophies.")
                sender_cards = [c["card_id"].lower() for c in await db.get_user_nba_cards(ctx.author.id)]
                if c_a["id"].lower() not in sender_cards:
                    return await ctx.send(f"❌ You do not own **{c_a['name']}** (`{c_a['id']}`).")
                cards_a.append(c_a)

        if their_card:
            c_b = get_nba_card(their_card)
            if not c_b:
                return await ctx.send(f"❌ The requested card `{their_card}` was not found.")
            if c_b.get("tier") == "exclusive" or str(c_b.get("id", "")).startswith("excl-") or c_b.get("is_exclusive"):
                return await ctx.send("❌ **Exclusive cards cannot be traded!** They are non-transferable account-bound trophies.")
            target_cards = [c["card_id"].lower() for c in await db.get_user_nba_cards(target.id)]
            if c_b["id"].lower() not in target_cards:
                return await ctx.send(f"❌ {target.mention} does not own **{c_b['name']}** (`{c_b['id']}`).")
            cards_b.append(c_b)

        embed = build_multi_trade_embed(ctx.author, target, cards_a, cards_b, status="pending", vc_a=init_vc_a)
        view = NBACardTradeView(ctx.author, target, cards_a, cards_b, vc_a=init_vc_a)
        msg = await ctx.send(
            content=f"🔔 {target.mention}, you have received a card & VC trade proposal from {ctx.author.mention}!",
            embed=embed,
            view=view
        )
        view.message = msg
    except Exception as e:
        logger.error(f"Error in !nbatrade: {e}", exc_info=True)
        await ctx.send(f"❌ Error: {e}")


@bot.command(name="nbatop", aliases=["nbaleaderboard", "topcards", "vctop", "nbalb"])
@commands.guild_only()
@commands.cooldown(1, 5.0, commands.BucketType.user)
async def nbatop_prefix_cmd(ctx: commands.Context, category: Optional[str] = "cards"):
    """View top NBA 2K Mobile Card Collectors or VC Millionaires: !nbatop [cards|vc]"""
    try:
        cat = (category or "cards").lower().strip()
        if cat == "vc":
            query = "SELECT user_id, vc_balance, cards_claimed FROM user_nba_economy WHERE user_id != '719932313919684670' ORDER BY vc_balance DESC LIMIT 10"
            rows = await db.fetch(query)
            embed = discord.Embed(
                title="🏆 NBA 2K Mobile • VC Millionaires Leaderboard",
                description="The richest Virtual Currency balances on the server!\n\n",
                color=discord.Color.gold()
            )
            if not rows:
                embed.description += "No VC records found yet. Claim daily VC with `!nbadaily`!"
            else:
                for idx, r in enumerate(rows, 1):
                    med = "🥇" if idx == 1 else "🥈" if idx == 2 else "🥉" if idx == 3 else f"**#{idx}**"
                    embed.description += f"{med} <@{r['user_id']}> — `💰 {r['vc_balance']:,} VC` *({r.get('cards_claimed', 0)} cards claimed)*\n"
        else:
            query = """
            SELECT user_id, COUNT(*) as total_cards, COUNT(DISTINCT card_id) as unique_cards
            FROM user_nba_cards
            WHERE user_id != '719932313919684670'
            GROUP BY user_id
            ORDER BY total_cards DESC
            LIMIT 10
            """
            rows = await db.fetch(query)
            embed = discord.Embed(
                title="🏆 NBA 2K Mobile • Top Card Collectors Leaderboard",
                description=f"The greatest card collectors on the server ({len(NBA_2K_MOBILE_CARDS)} cards in catalog)!\n\n",
                color=discord.Color.purple()
            )
            if not rows:
                embed.description += "No cards collected yet! Open your first pack with `!openpack`!"
            else:
                for idx, r in enumerate(rows, 1):
                    med = "🥇" if idx == 1 else "🥈" if idx == 2 else "🥉" if idx == 3 else f"**#{idx}**"
                    embed.description += f"{med} <@{r['user_id']}> — `🎴 {r['total_cards']} Cards` *({r['unique_cards']}/{len(NBA_2K_MOBILE_CARDS)} unique)*\n"

        embed.set_footer(text="NBA 2K Mobile Dex Leaderboard • Use !nbadex to view your collection")
        embed.timestamp = discord.utils.utcnow()
        await ctx.send(embed=embed)
    except Exception as e:
        logger.error(f"Error in !nbatop: {e}", exc_info=True)
        await ctx.send(f"❌ Error: {e}")


@bot.command(name="nbafav", aliases=["favcard", "favoritecard", "fav"])
@commands.guild_only()
@commands.cooldown(1, 3.0, commands.BucketType.user)
async def nbafav_prefix_cmd(ctx: commands.Context, *, card_query: str):
    """Toggle favorite status for an NBA card: !nbafav <card_id or name>"""
    try:
        card_obj = get_nba_card(card_query)
        if not card_obj:
            await ctx.send(f"❌ Card `{card_query}` not found in catalog.")
            return

        user_cards = await db.get_user_nba_cards(ctx.author.id)
        matching = [c for c in user_cards if c["card_id"].lower() == card_obj["id"].lower()]
        if not matching:
            await ctx.send(f"❌ You do not own **{card_obj['name']}** in your binder.")
            return

        curr_fav = any(c.get("is_favorite") for c in matching)
        new_fav = not curr_fav
        await db.execute("UPDATE user_nba_cards SET is_favorite = ? WHERE user_id = ? AND card_id = ?", new_fav, str(ctx.author.id), card_obj["id"])

        status_str = "⭐ Marked as **Favorite**" if new_fav else "Removed from Favorites"
        await ctx.send(f"✅ **{card_obj['name']}** [{card_obj['ovr']} OVR] has been {status_str}!")
    except Exception as e:
        logger.error(f"Error in !nbafav: {e}", exc_info=True)
        await ctx.send(f"❌ Error: {e}")


