@bot.command(name="nbagrant", aliases=["grantcard", "exclgrant", "grantexclusive", "grant"])
async def nbagrant_prefix_cmd(ctx: commands.Context, *, raw_args: str = ""):
    """Grant an Exclusive or rare card directly:
    !nbagrant [target] [count] <card_name>
    Examples:
      !nbagrant Michael Jordan
      !nbagrant excl-jordan-99
      !nbagrant @Naraito 2 LeBron 99
    """
    try:
        is_creator = str(ctx.author.id) == "719932313919684670"
        if not is_creator:
            return await ctx.send("❌ This command is strictly restricted to the Bot Creator (ID: `719932313919684670`).")

        raw = raw_args.strip()
        if not raw:
            return await ctx.send(
                "👑 **NBA Card Grant Usage:**\n"
                "• `!nbagrant <card_name>` — Grant to yourself (e.g. `!nbagrant Michael Jordan`)\n"
                "• `!nbagrant @user <card_name>` — Grant to a member (e.g. `!nbagrant @user Kobe Bryant`)\n"
                "• `!nbagrant @user 3 <card_name>` — Grant multiple copies"
            )

        tokens = raw.split()
        target = ctx.author
        count = 1
        idx = 0

        first_tok = tokens[0]
        m_match = re.match(r'^<@!?(\d+)>$', first_tok)
        if m_match:
            uid = int(m_match.group(1))
            found_mem = ctx.guild.get_member(uid) if ctx.guild else None
            if found_mem:
                target = found_mem
            idx += 1
        elif first_tok.isdigit() and len(first_tok) >= 17:
            uid = int(first_tok)
            found_mem = ctx.guild.get_member(uid) if ctx.guild else None
            if found_mem:
                target = found_mem
            idx += 1

        if idx < len(tokens) and tokens[idx].isdigit() and len(tokens[idx]) <= 3:
            count = max(1, min(int(tokens[idx]), 50))
            idx += 1

        query = " ".join(tokens[idx:]).strip()
        if not query:
            return await ctx.send("❌ Please specify the card name or ID to grant! Example: `!nbagrant Michael Jordan`")

        card_obj = get_nba_card(query)
        if not card_obj:
            return await ctx.send(f"❌ Card `{query}` was not found in the NBA 2K catalog.")

        for _ in range(count):
            await db.add_user_nba_card(target.id, card_obj["id"], source="creator_grant")

        tier_info = NBA_2K_TIERS.get(card_obj["tier"], NBA_2K_TIERS["gold"])
        embed = discord.Embed(
            title="👑 [ EXCLUSIVE GRANT ] • NBA 2K CARD DELIVERED",
            description=(
                f"🌟 **Card Granted By**: {ctx.author.mention}\n"
                f"👤 **Recipient**: {target.mention}\n\n"
                f"• 🎴 **Card**: {tier_info['emoji']} **[{card_obj['ovr']} OVR] {card_obj['name']}** `[x{count}]`\n"
                f"• 🏆 **Tier**: **{tier_info['name']}**\n"
                f"• ⚡ **Theme / Moment**: *{card_obj.get('theme', 'Exclusive Masterpiece')}*\n"
                f"• 🔑 **Card ID**: `{card_obj['id']}`\n\n"
                f"✨ *The card has been safely added directly to {target.display_name}'s collection binder!*"
            ),
            color=tier_info["color"]
        )
        card_buf = generate_nba_card_graphic(card_obj)
        card_file = discord.File(fp=card_buf, filename="granted_card.png")
        embed.set_image(url="attachment://granted_card.png")
        embed.set_footer(text="NBA 2K Official Card Grant • View in Binder with !nbadex")
        embed.timestamp = discord.utils.utcnow()

        await ctx.send(embed=embed, file=card_file)
    except Exception as e:
        logger.error(f"Error in !nbagrant: {e}", exc_info=True)
        await ctx.send(f"❌ Error granting card: {e}")


@bot.command(name="stripexclusives", aliases=["stripallexclusives", "purgeexclusives", "nbarevokeexcl", "nbastripexl", "stripall", "purgeall"])
async def stripexclusives_prefix_cmd(ctx: commands.Context, *, raw_args: str = ""):
    """Strip away all Exclusive cards from a user or globally across all users (Creator Only):
    • !stripexclusives @user  (Strip all exclusives from a specific user)
    • !stripexclusives all    (Global strip from all users except creator)
    """
    try:
        is_creator = str(ctx.author.id) == "719932313919684670"
        if not is_creator:
            return await ctx.send("❌ This command is strictly restricted to the Bot Creator (ID: `719932313919684670`).")

        raw = raw_args.strip().lower()
        if not raw:
            return await ctx.send(
                "🛡️ **NBA Exclusive Strip Usage:**\n"
                "• `!stripexclusives @user` — Strip all exclusive cards from a member\n"
                "• `!stripexclusives all` or `!stripallexclusives` — Strip all exclusive cards globally (protects creator)"
            )

        excl_catalog_ids = [c["id"] for c in NBA_2K_MOBILE_CARDS if c.get("tier") == "exclusive"]

        target_uid = None
        target_display = None
        if ctx.message.mentions:
            target_uid = str(ctx.message.mentions[0].id)
            target_display = ctx.message.mentions[0].mention
        else:
            first_word = raw.split()[0].strip("<@!>") if raw.split() else ""
            if first_word.isdigit() and len(first_word) >= 17:
                target_uid = first_word
                target_display = f"<@{first_word}> (`{first_word}`)"

        if target_uid:
            total_deleted, affected = await db.strip_exclusive_cards(
                target_user_id=target_uid,
                catalog_exclusive_ids=excl_catalog_ids
            )
            embed = discord.Embed(
                title="🛡️ [ EXCLUSIVE STRIP ] • CARDS REVOKED",
                description=(
                    f"✅ Successfully stripped **`{total_deleted:,}` Exclusive cards** from {target_display}!\n\n"
                    f"• **Target User:** {target_display}\n"
                    f"• **Cards Removed:** `{total_deleted:,}`\n"
                    f"• **Action Executed By:** {ctx.author.mention}"
                ),
                color=discord.Color.red()
            )
            embed.set_footer(text="NBA 2K Exclusive Security Protocol")
            embed.timestamp = discord.utils.utcnow()
            return await ctx.send(embed=embed)

        if raw in ["all", "global", "everyone", "all_users", "purge"]:
            total_deleted, total_users = await db.strip_exclusive_cards(
                target_user_id=None,
                exclude_creator_id="719932313919684670",
                catalog_exclusive_ids=excl_catalog_ids
            )
            embed = discord.Embed(
                title="🛡️ [ GLOBAL EXCLUSIVE STRIP ] • ALL EXCLUSIVES PURGED",
                description=(
                    f"🚨 **Global Exclusive Card Purge Completed!**\n\n"
                    f"• 🗑️ **Total Exclusive Cards Revoked:** `{total_deleted:,}`\n"
                    f"• 👥 **Affected Users:** `{total_users:,}`\n"
                    f"• 👑 **Creator Card Binder:** *Safely Protected & Preserved*\n"
                    f"• 🔒 **Executed By:** {ctx.author.mention}"
                ),
                color=discord.Color.dark_red()
            )
            embed.set_footer(text="NBA 2K Global Card Integrity Sweep")
            embed.timestamp = discord.utils.utcnow()
            return await ctx.send(embed=embed)

        return await ctx.send("❌ Invalid syntax. Use `!stripexclusives @user` or `!stripexclusives <user_id>` or `!stripexclusives all`.")
    except Exception as e:
        logger.error(f"Error in !stripexclusives: {e}", exc_info=True)
        await ctx.send(f"❌ Error stripping exclusive cards: {e}")


@bot.tree.command(name="spawndrop", description="🏀 Instantly trigger a wild NBA 2K Mobile player card drop in chat (Staff)")
@app_commands.describe(
    tier="Specific card tier rarity to spawn (Dark Matter / Galaxy Opal reserved for Server Owner)",
    channel="Target public text channel (defaults to current channel)"
)
@app_commands.choices(tier=[
    app_commands.Choice(name="🎲 Randomized Drop Roll", value="random"),
    app_commands.Choice(name="🌌 Dark Matter (99 OVR - Owner Only)", value="dark_matter"),
    app_commands.Choice(name="✨ Galaxy Opal (97-98 OVR - Owner Only)", value="galaxy_opal"),
    app_commands.Choice(name="💎 Diamond (93-96 OVR)", value="diamond"),
    app_commands.Choice(name="🔮 Amethyst (88-92 OVR)", value="amethyst"),
    app_commands.Choice(name="🔴 Ruby (84-87 OVR)", value="ruby"),
    app_commands.Choice(name="🟡 Gold (75-83 OVR)", value="gold"),
])
@app_commands.default_permissions(manage_messages=True)
@app_commands.guild_only()
@app_commands.checks.cooldown(1, 3.0, key=lambda i: (i.guild_id, i.user.id))
async def spawndrop_slash_cmd(
    interaction: discord.Interaction,
    tier: Optional[str] = "random",
    channel: Optional[discord.TextChannel] = None
):
    try:
        is_owner = is_server_owner_or_creator(interaction.user, interaction.guild)
        if not is_owner and not interaction.permissions.manage_messages:
            return await interaction.response.send_message("❌ Only server staff with `Manage Messages` permission can spawn card drops.", ephemeral=True)
        
        target_chan = channel or interaction.channel
        if not isinstance(target_chan, discord.TextChannel):
            return await interaction.response.send_message("❌ Invalid text channel selected.", ephemeral=True)

        # 1. Anti-Abuse: Block fully hidden staff-only channels UNLESS it's the server's configured drop channel
        configured_drop_id = await db.get_config(target_chan.guild.id, "nba_drop_channel", None)
        is_configured_channel = configured_drop_id and str(target_chan.id) == str(configured_drop_id)
        if not is_configured_channel and is_staff_only_hidden_channel(target_chan):
            return await interaction.response.send_message(
                "❌ **Drop Blocked**: Card drops cannot be spawned in private/hidden channels that the community cannot see.\n"
                "💡 *Set a dedicated drop channel with `!setnbachannel #channel`, or use a channel everyone can view.*",
                ephemeral=True
            )

        t_req = None if (not tier or tier == "random") else tier.lower().strip()

        # 2. Anti-Abuse: Top tiers (Dark Matter / Galaxy Opal) are Server Owner exclusive
        if t_req in ["dark_matter", "galaxy_opal"] and not is_owner:
            return await interaction.response.send_message(
                "❌ **Restricted Tier**: Manually spawning **Dark Matter (99 OVR)** or **Galaxy Opal (97-98 OVR)** cards is reserved exclusively for the Server Owner.\n"
                "💡 *Staff members can spawn Diamond (93-96), Amethyst (88-92), Ruby (84-87), Gold (75-83), or Randomized Drop.*",
                ephemeral=True
            )

        # 3. Anti-Abuse: Daily spawn limit (max 2 manual spawns per staff member per 24h)
        allowed, cur_cnt, max_limit = check_staff_daily_spawn_limit(interaction.user.id, is_owner)
        if not allowed:
            return await interaction.response.send_message(
                f"⏳ **Daily Drop Limit Reached**: You have used **{cur_cnt}/{max_limit}** manual card drops for the day. Drops reset 24 hours after each use.",
                ephemeral=True
            )

        # 4. Spawn drop with host spawner tracked (Host cannot claim their own drop)
        await spawn_nba_card_drop(target_chan, requested_tier=t_req, spawner=interaction.user)
        await interaction.response.send_message(f"🏀 Wild NBA card drop triggered in {target_chan.mention}! *(Host is disqualified from catching)*", ephemeral=True)
    except Exception as e:
        logger.error(f"Error in /spawndrop: {e}", exc_info=True)
        if interaction.response.is_done():
            await interaction.followup.send(f"❌ Error: {e}", ephemeral=True)
        else:
            await interaction.response.send_message(f"❌ Error: {e}", ephemeral=True)


